on conflict (id) do nothing;


-- ============================================================
-- apps/cortex-core-api/supabase/migration_studio_capture.sql
-- ============================================================

-- Lexica Studio: capture posts while browsing (browser extension, Android share,
-- iOS Shortcut). Captured posts become signals that show up in Studio → Radar.
-- Requires migration_studio.sql and migration_studio_phase2.sql. Idempotent.

-- Captures are a new source kind
alter table studio_sources drop constraint if exists studio_sources_kind_check;
alter table studio_sources add constraint studio_sources_kind_check
  check (kind in ('google_trends','rss','youtube','manual','capture'));

insert into studio_sources (id, kind, label, weight, config, enabled) values
  ('capture_threads', 'capture', 'Gửi từ Threads', 2.0, '{}', true),
  ('capture_facebook', 'capture', 'Gửi từ Facebook', 2.0, '{}', true),
  ('capture_tiktok', 'capture', 'Gửi từ TikTok', 2.0, '{}', true),
  ('capture_web', 'capture', 'Gửi từ web khác', 1.5, '{}', true)
on conflict (id) do nothing;

-- Extra fields for captured posts (collector signals leave them null)
alter table studio_signals add column if not exists body text
  check (body is null or char_length(body) <= 2000);
alter table studio_signals add column if not exists author text
  check (author is null or char_length(author) <= 100);
alter table studio_signals add column if not exists note text
  check (note is null or char_length(note) <= 500);
alter table studio_signals add column if not exists metrics jsonb;
alter table studio_signals add column if not exists captured_by uuid references auth.users(id) on delete set null;
alter table studio_signals add column if not exists dismissed boolean not null default false;
create index if not exists studio_signals_captured_idx
  on studio_signals (captured_by, seen_at desc) where captured_by is not null;

-- Long-lived tokens for the extension and the iOS Shortcut. Only a SHA-256
-- hash is stored; a token can only add captures for its owner.
create table if not exists studio_capture_tokens (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references auth.users(id) on delete cascade,
  name text not null check (char_length(name) <= 60),
  token_hash text not null unique,
  created_at timestamptz not null default now(),
  last_used_at timestamptz,
  revoked_at timestamptz
);

alter table studio_capture_tokens enable row level security;
drop policy if exists "studio_capture_tokens editors" on studio_capture_tokens;
create policy "studio_capture_tokens editors" on studio_capture_tokens
  for all using (is_studio_editor() and user_id = auth.uid())
  with check (is_studio_editor() and user_id = auth.uid());

-- Called by the Cortex API (POST /capture) with the anon key. Checks the
-- token hash, then stores the capture. The same link captured again within
-- 7 days returns the earlier capture (and keeps the newest note) instead of
-- a duplicate.
create or replace function studio_capture_with_token(p_token_hash text, p_capture jsonb)
returns bigint
language plpgsql
security definer
set search_path = public
as $$
declare
  v_user uuid;
  v_token uuid;
  v_id bigint;
  v_source text := coalesce(p_capture->>'source_id', 'capture_web');
  v_url text := nullif(p_capture->>'url', '');
begin
  select id, user_id into v_token, v_user
  from studio_capture_tokens
  where token_hash = p_token_hash and revoked_at is null;
  if v_user is null or not exists (select 1 from studio_editors where user_id = v_user) then
    raise exception 'invalid capture token' using errcode = '28000';
  end if;
  if v_source not like 'capture\_%' or not exists (select 1 from studio_sources where id = v_source) then
    v_source := 'capture_web';
  end if;

  update studio_capture_tokens set last_used_at = now() where id = v_token;

  if v_url is not null then
    select id into v_id from studio_signals
    where url = v_url and captured_by = v_user and seen_at > now() - interval '7 days'
    order by seen_at desc limit 1;
    if v_id is not null then
      update studio_signals set
        note = coalesce(nullif(p_capture->>'note', ''), note),
        body = coalesce(body, nullif(p_capture->>'body', '')),
        dismissed = false
      where id = v_id;
      return v_id;
    end if;
  end if;

  insert into studio_signals (source_id, phrase, context, url, metric, body, author, note, metrics, captured_by)
  values (
    v_source,
    left(coalesce(nullif(p_capture->>'phrase', ''), '(chưa có nội dung)'), 160),
    left(nullif(p_capture->>'context', ''), 300),
    v_url,
    1,
    left(nullif(p_capture->>'body', ''), 2000),
    left(nullif(p_capture->>'author', ''), 100),
    left(nullif(p_capture->>'note', ''), 500),
    case when jsonb_typeof(p_capture->'metrics') = 'object' then p_capture->'metrics' end,
    v_user
  )
  returning id into v_id;
  return v_id;
end;
$$;

revoke all on function studio_capture_with_token(text, jsonb) from public;
grant execute on function studio_capture_with_token(text, jsonb) to anon, authenticated;

-- Lets the extension's "Kiểm tra" button confirm a token without saving
-- anything. Returns the token's name, or null when it is unknown or revoked.
create or replace function studio_capture_token_name(p_token_hash text)
returns text
language sql
stable
security definer
set search_path = public
as $$
  select t.name from studio_capture_tokens t
  join studio_editors e on e.user_id = t.user_id
  where t.token_hash = p_token_hash and t.revoked_at is null;
$$;

revoke all on function studio_capture_token_name(text) from public;
grant execute on function studio_capture_token_name(text) to anon, authenticated;


-- ============================================================
-- apps/cortex-core-api/supabase/migration_studio_variants.sql
-- ============================================================

-- Example sentences per learner archetype (docs: variants.ts in the studio
-- module). Each card's own scenario is the casual one; Studio writes a tech,
-- a business and a student version, editors approve them, and the approved
-- ones ship as one overlay file listed in the content manifest.
-- Requires migration_studio.sql. Idempotent.

-- Lexica's bundled core cards, so Studio can write variants for them too.
-- Filled by seed_studio_core_cards.sql (scripts/build-studio-core-cards.py).
create table if not exists studio_core_cards (
  id text primary key,                            -- 'v###'
  word text not null,
  scenario text not null,
  translation_hint text not null,
  level text not null check (level in ('beginner','intermediate','advanced','expert')),
  elo int not null
);

create table if not exists studio_card_variants (
  card_id text not null,                          -- core 'v###' or Studio 't…'
  archetype text not null check (archetype in ('tech','business','student')),
  scenario text not null,
  status text not null default 'pending' check (status in ('pending','approved','rejected')),
  model text,
  prompt_version text,
  reviewer_id uuid references auth.users(id),
  reviewed_at timestamptz,
  created_at timestamptz not null default now(),
  primary key (card_id, archetype)
);
create index if not exists studio_card_variants_status_idx on studio_card_variants (status, created_at);

do $$
declare t text;
begin
  foreach t in array array['studio_core_cards','studio_card_variants']
  loop
    execute format('alter table %I enable row level security', t);
    execute format('drop policy if exists "%s editors" on %I', t, t);
    execute format('create policy "%s editors" on %I for all using (is_studio_editor()) with check (is_studio_editor())', t, t);
  end loop;
end $$;


-- ============================================================
-- apps/cortex-core-api/supabase/migration_studio_quotes.sql
-- ============================================================

-- Lexica "Ngoài đời": real quotes that contain a card's word (books, headlines,
-- song lines). Editors review every row before it is published with the
-- archetype overlay (variants.service.ts publish).
create table if not exists studio_card_quotes (
  id uuid primary key default gen_random_uuid(),
  card_id text not null,                          -- core 'v###' or Studio 't…'
  kind text not null check (kind in ('book','news','song')),
  text text not null,
  translation text,
  source text not null,                           -- "Pride and Prejudice — Jane Austen"
  url text,
  status text not null default 'pending' check (status in ('pending','approved','rejected')),
  reviewer_id uuid references auth.users(id),
  reviewed_at timestamptz,
  created_at timestamptz not null default now()
);
create index if not exists studio_card_quotes_status_idx on studio_card_quotes (status, created_at);

alter table studio_card_quotes enable row level security;
drop policy if exists "studio_card_quotes editors" on studio_card_quotes;
create policy "studio_card_quotes editors" on studio_card_quotes
  for all using (is_studio_editor()) with check (is_studio_editor());


-- ============================================================
-- apps/cortex-core-api/supabase/migration_studio_collocations_media.sql
-- ============================================================

-- Collocations ("Hay đi với") on Studio drafts and cards, and an optional
-- media clip on quotes (a YouTube video with start/end seconds for song lines).
-- Safe to re-run.
alter table studio_drafts add column if not exists collocations text[] not null default '{}';
alter table studio_cards add column if not exists collocations text[] not null default '{}';
alter table studio_card_quotes add column if not exists media jsonb;


-- ============================================================
-- apps/cortex-core-api/supabase/migration_studio_corpus.sql
-- ============================================================

-- Lexica "Ngoài đời" v2: a sentence corpus built once from public-domain books
-- (src/modules/studio/corpus/books.ts), searched by lemma instead of asking
-- Gutendex per word. Also records which cards were searched, and when the
-- approved quotes were last published. Safe to re-run.

create table if not exists studio_corpus_books (
  id text primary key,                         -- 'pg1342'
  gutenberg_id int not null,
  title text not null,
  author text not null,
  sentences int not null default 0,
  built_at timestamptz,
  error text                                   -- last download/parse failure
);

create table if not exists studio_corpus_sentences (
  id bigserial primary key,
  book_id text not null references studio_corpus_books(id) on delete cascade,
  text text not null check (char_length(text) between 40 and 220),
  lemmas text[] not null
);
create index if not exists studio_corpus_sentences_lemmas_idx
  on studio_corpus_sentences using gin (lemmas);
create index if not exists studio_corpus_sentences_book_idx
  on studio_corpus_sentences (book_id);

-- One row per card that was searched; the nightly job skips cards searched
-- since the corpus last changed, so "Tìm" always moves on to new cards.
create table if not exists studio_quote_attempts (
  card_id text primary key,
  tried_at timestamptz not null default now(),
  found int not null default 0
);

alter table studio_card_quotes add column if not exists published_at timestamptz;

do $$
declare t text;
begin
  foreach t in array array['studio_corpus_books','studio_corpus_sentences','studio_quote_attempts']
  loop
    execute format('alter table %I enable row level security', t);
    execute format('drop policy if exists "%s editors" on %I', t, t);
    execute format('create policy "%s editors" on %I for all using (is_studio_editor()) with check (is_studio_editor())', t, t);
  end loop;
end $$;


-- ============================================================
-- apps/cortex-core-api/supabase/migration_studio_passages.sql
-- ============================================================

-- Lexica "Đọc" passages (docs/LEXICA_FEEDBACK_TASKS.md T7): short English
-- texts written around 3–5 deck words, reviewed by an editor and published as
-- a pack (manifest `passages`). Safe to re-run.
create table if not exists studio_passages (
  id uuid primary key default gen_random_uuid(),
  level text not null check (level in ('beginner','intermediate','advanced','expert')),
  topic text not null,
  title text not null,
  text text not null,
  translation text not null,
  new_words text[] not null,                     -- card ids the passage introduces
  words text[] not null default '{}',            -- other deck card ids in the text
  questions jsonb not null default '[]',
  status text not null default 'pending' check (status in ('pending','approved','rejected')),
  model text,
  prompt_version text,
  created_by uuid references auth.users(id),
  reviewer_id uuid references auth.users(id),
  reviewed_at timestamptz,
  published_at timestamptz,
  created_at timestamptz not null default now()
);
create index if not exists studio_passages_status_idx on studio_passages (status, created_at);

alter table studio_passages enable row level security;
drop policy if exists "studio_passages editors" on studio_passages;
create policy "studio_passages editors" on studio_passages
  for all using (is_studio_editor()) with check (is_studio_editor());


-- ============================================================
-- apps/cortex-core-api/supabase/migration_studio_talk.sql
-- ============================================================

-- Lexica Giao tiếp branch (docs/LEXICA_DIRECTION.md): phrase cards with a
-- situation to say them in, reviewed by an editor and published as the
-- `talk` card pack; dialogues are passages of kind 'dialogue'.
-- Requires migration_studio_passages.sql. Safe to re-run.
create table if not exists studio_talk_cards (
  id uuid primary key default gen_random_uuid(),
  card_id text not null unique,                 -- 'k…' for Studio phrases, 'g###' for the ones bundled in the app
  core boolean not null default false,          -- bundled in the app: never published in the pack
  level text not null check (level in ('beginner','intermediate','advanced','expert')),
  topic text not null,
  phrase text not null,
  scenario text not null,
  translation_hint text not null,
  situation_prompt text not null,
  situation_model text not null,
  status text not null default 'pending' check (status in ('pending','approved','rejected')),
  model text,
  prompt_version text,
  created_by uuid references auth.users(id),
  reviewer_id uuid references auth.users(id),
  reviewed_at timestamptz,
  published_at timestamptz,
  created_at timestamptz not null default now()
);
create index if not exists studio_talk_cards_status_idx on studio_talk_cards (status, created_at);
create unique index if not exists studio_talk_cards_phrase_idx on studio_talk_cards (phrase) where status <> 'rejected';

alter table studio_talk_cards enable row level security;
drop policy if exists "studio_talk_cards editors" on studio_talk_cards;
create policy "studio_talk_cards editors" on studio_talk_cards
  for all using (is_studio_editor()) with check (is_studio_editor());

alter table studio_passages add column if not exists kind text not null default 'text';
alter table studio_passages drop constraint if exists studio_passages_kind_check;
alter table studio_passages add constraint studio_passages_kind_check check (kind in ('text','dialogue'));


