-- ============================================================
-- apps/lexica/supabase/migration_engagement.sql
-- ============================================================

-- Lexica collection economy (docs/LEXICA_ENGAGEMENT_SPEC.md §2): minting
-- card editions, boxes, dust, reroll tickets, streak freezes.
--
-- Everything that changes a wallet runs inside these security-definer
-- functions, called by signed-in users with their own session
-- (supabase.rpc). Users can read their own rows but never write them, so the
-- odds, pity counters and daily caps are enforced here, not in the app.
-- Idempotent: safe to re-run. Requires migration_phase1_core.sql (app_backups).

-- ------------------------------------------------------------------ tables

create table if not exists public.lexica_card_editions (
  user_id uuid references auth.users(id) on delete cascade,
  card_id text not null check (char_length(card_id) <= 40),
  edition text not null check (edition in ('common','silver','holo','legendary')),
  serial int,                                  -- legendary only
  minted_at timestamptz not null default now(),
  rerolls int not null default 0,
  primary key (user_id, card_id)
);

create sequence if not exists public.lexica_legendary_serial;

create table if not exists public.lexica_wallet (
  user_id uuid primary key references auth.users(id) on delete cascade,
  boxes int not null default 0,
  pending_boxes int not null default 0,        -- earned over today's cap, delivered tomorrow
  dust int not null default 0,
  reroll_tickets int not null default 0,
  streak_freezes int not null default 0,
  since_holo int not null default 0,
  since_legendary int not null default 0,
  mints_total int not null default 0,
  mints_today int not null default 0,
  boxes_today int not null default 0,
  day date
);

-- Every change to a wallet, for auditing and undoing mistakes.
create table if not exists public.lexica_wallet_ledger (
  id bigserial primary key,
  user_id uuid not null references auth.users(id) on delete cascade,
  kind text not null,
  delta jsonb not null,
  ref text,
  at timestamptz not null default now()
);
create index if not exists lexica_wallet_ledger_user_idx on public.lexica_wallet_ledger (user_id, at desc);
-- One reward per claim (daily goal of a date, a set, a streak milestone…).
create unique index if not exists lexica_wallet_ledger_claim_idx
  on public.lexica_wallet_ledger (user_id, kind, ref) where kind like 'claim:%';

-- When the server first saw a learned card in the user's synced progress.
-- Minting needs 7 real days since then, which a forged backup cannot skip.
create table if not exists public.lexica_card_first_seen (
  user_id uuid references auth.users(id) on delete cascade,
  card_id text not null,
  first_seen_at timestamptz not null default now(),
  primary key (user_id, card_id)
);

-- Tunable numbers (odds, prices, caps). Change a row, no deploy needed.
create table if not exists public.lexica_engagement_config (
  key text primary key,
  value jsonb not null
);
insert into public.lexica_engagement_config (key, value) values
  ('mint_odds', '{"silver": 0.15, "holo": 0.045, "legendary": 0.005}'),
  ('pity', '{"holo_after": 30, "legendary_soft_after": 200, "legendary_soft_step": 0.005}'),
  ('mint_rules', '{"min_days": 7, "min_reviews": 3, "max_per_day": 30, "box_every": 10}'),
  ('boxes', '{"daily_cap": 3, "pending_max": 10, "daily_goal": 1, "set_complete": 2, "ghost_streak": 1, "streak_7": 1, "streak_30": 3, "streak_100": 5}'),
  ('box_table', '[{"item":"dust","amount":20,"p":0.55},{"item":"dust","amount":50,"p":0.20},{"item":"freeze","amount":1,"p":0.12},{"item":"ticket","amount":1,"p":0.10},{"item":"dust","amount":150,"p":0.03}]'),
  ('prices', '{"ticket": 120, "upgrade_silver": 300, "freeze_max": 2, "refund_common": 10, "refund_silver": 25, "freeze_full_dust": 30}')
on conflict (key) do nothing;

alter table public.lexica_card_editions enable row level security;
alter table public.lexica_wallet enable row level security;
alter table public.lexica_wallet_ledger enable row level security;
alter table public.lexica_card_first_seen enable row level security;
alter table public.lexica_engagement_config enable row level security;

drop policy if exists "lexica_card_editions own read" on public.lexica_card_editions;
create policy "lexica_card_editions own read" on public.lexica_card_editions for select using (user_id = auth.uid());
drop policy if exists "lexica_wallet own read" on public.lexica_wallet;
create policy "lexica_wallet own read" on public.lexica_wallet for select using (user_id = auth.uid());
drop policy if exists "lexica_wallet_ledger own read" on public.lexica_wallet_ledger;
create policy "lexica_wallet_ledger own read" on public.lexica_wallet_ledger for select using (user_id = auth.uid());
drop policy if exists "lexica_card_first_seen own read" on public.lexica_card_first_seen;
create policy "lexica_card_first_seen own read" on public.lexica_card_first_seen for select using (user_id = auth.uid());
drop policy if exists "lexica_engagement_config read" on public.lexica_engagement_config;
create policy "lexica_engagement_config read" on public.lexica_engagement_config for select using (true);

-- ---------------------------------------------------------------- helpers

create or replace function public.lexica_cfg(p_key text)
returns jsonb language sql stable security definer set search_path = public as $$
  select value from lexica_engagement_config where key = p_key;
$$;

create or replace function public.lexica_today()
returns date language sql stable as $$
  select (now() at time zone 'Asia/Ho_Chi_Minh')::date;
$$;

create or replace function public.lexica_edition_rank(p_edition text)
returns int language sql immutable as $$
  select case p_edition when 'common' then 0 when 'silver' then 1 when 'holo' then 2 when 'legendary' then 3 else -1 end;
$$;

-- Locks and returns the caller's wallet, creating it and rolling the day over.
create or replace function public.lexica_wallet_for_update(p_user uuid)
returns public.lexica_wallet language plpgsql security definer set search_path = public as $$
declare
  w lexica_wallet;
  cap int := (lexica_cfg('boxes')->>'daily_cap')::int;
  deliver int;
begin
  insert into lexica_wallet (user_id, day) values (p_user, lexica_today()) on conflict (user_id) do nothing;
  select * into w from lexica_wallet where user_id = p_user for update;
  if w.day is distinct from lexica_today() then
    deliver := least(w.pending_boxes, cap);
    update lexica_wallet set
      day = lexica_today(), mints_today = 0,
      boxes_today = deliver, boxes = boxes + deliver, pending_boxes = pending_boxes - deliver
    where user_id = p_user returning * into w;
    if deliver > 0 then
      insert into lexica_wallet_ledger (user_id, kind, delta) values (p_user, 'box_delivered', jsonb_build_object('boxes', deliver));
    end if;
  end if;
  return w;
end;
$$;

-- Adds boxes within today's cap; the rest waits for tomorrow (up to pending_max).
create or replace function public.lexica_grant_boxes(p_user uuid, p_count int, p_kind text, p_ref text)
returns int language plpgsql security definer set search_path = public as $$
declare
  w lexica_wallet := lexica_wallet_for_update(p_user);
  cap int := (lexica_cfg('boxes')->>'daily_cap')::int;
  pending_max int := (lexica_cfg('boxes')->>'pending_max')::int;
  now_count int := greatest(0, least(p_count, cap - w.boxes_today));
  later int := least(p_count - now_count, pending_max - w.pending_boxes);
begin
  later := greatest(later, 0);
  update lexica_wallet set
    boxes = boxes + now_count, boxes_today = boxes_today + now_count, pending_boxes = pending_boxes + later
  where user_id = p_user;
  insert into lexica_wallet_ledger (user_id, kind, delta, ref)
  values (p_user, p_kind, jsonb_build_object('boxes', now_count, 'pending', later), p_ref);
  return now_count;
end;
$$;

-- One edition roll. p_pity = false for rerolls (base odds, counters untouched).
create or replace function public.lexica_roll_edition(p_user uuid, p_pity boolean)
returns text language plpgsql security definer set search_path = public as $$
declare
  w lexica_wallet;
  odds jsonb := lexica_cfg('mint_odds');
  pity jsonb := lexica_cfg('pity');
  p_leg numeric := (odds->>'legendary')::numeric;
  p_holo numeric := (odds->>'holo')::numeric;
  p_silver numeric := (odds->>'silver')::numeric;
  r numeric := random();
  result text;
begin
  if p_pity then
    select * into w from lexica_wallet where user_id = p_user;
    if w.since_legendary >= (pity->>'legendary_soft_after')::int then
      p_leg := p_leg + (pity->>'legendary_soft_step')::numeric * (w.since_legendary - (pity->>'legendary_soft_after')::int + 1);
    end if;
    -- Hard pity: after holo_after mints without Holo, the next is Holo or better.
    if w.since_holo >= (pity->>'holo_after')::int then
      result := case when random() < p_leg / (p_leg + p_holo) then 'legendary' else 'holo' end;
    end if;
  end if;
  if result is null then
    result := case
      when r < p_leg then 'legendary'
      when r < p_leg + p_holo then 'holo'
      when r < p_leg + p_holo + p_silver then 'silver'
      else 'common' end;
  end if;
  if p_pity then
    update lexica_wallet set
      since_holo = case when lexica_edition_rank(result) >= 2 then 0 else since_holo + 1 end,
      since_legendary = case when result = 'legendary' then 0 else since_legendary + 1 end
    where user_id = p_user;
  end if;
  return result;
end;
$$;

-- The caller's synced progress for one card (from the Lexica backup).
create or replace function public.lexica_backup_progress(p_user uuid)
returns jsonb language sql stable security definer set search_path = public as $$
  select coalesce(raw_data->'state'->'state'->'cardProgress', '{}'::jsonb)
  from app_backups where user_id = p_user and app_source = 'lexica';
$$;

-- --------------------------------------------------------------- public API

-- Wallet, editions, cards ready to mint, public odds. Also records first
-- sightings of learned cards, which start their 7-day mint clock.
create or replace function public.lexica_engagement_state()
returns jsonb language plpgsql security definer set search_path = public as $$
declare
  uid uuid := auth.uid();
  w lexica_wallet;
  progress jsonb;
  rules jsonb := lexica_cfg('mint_rules');
begin
  if uid is null then raise exception 'not signed in' using errcode = '28000'; end if;
  w := lexica_wallet_for_update(uid);
  progress := coalesce(lexica_backup_progress(uid), '{}'::jsonb);

  insert into lexica_card_first_seen (user_id, card_id)
  select uid, key from jsonb_object_keys(progress) as key
  where char_length(key) <= 40
  on conflict do nothing;

  return jsonb_build_object(
    'wallet', to_jsonb(w) - 'user_id',
    'editions', coalesce((
      select jsonb_object_agg(card_id, jsonb_build_object('edition', edition, 'serial', serial, 'rerolls', rerolls))
      from lexica_card_editions where user_id = uid), '{}'::jsonb),
    'ready', coalesce((
      select jsonb_agg(f.card_id order by f.first_seen_at)
      from lexica_card_first_seen f
      where f.user_id = uid
        and f.first_seen_at <= now() - make_interval(days => (rules->>'min_days')::int)
        and progress->f.card_id->>'state' = 'mastered'
        and coalesce((progress->f.card_id->>'reviewCount')::int, 0) >= (rules->>'min_reviews')::int
        and not exists (select 1 from lexica_card_editions e where e.user_id = uid and e.card_id = f.card_id)
    ), '[]'::jsonb),
    'waiting', coalesce((
      select jsonb_object_agg(f.card_id, f.first_seen_at + make_interval(days => (rules->>'min_days')::int))
      from lexica_card_first_seen f
      where f.user_id = uid
        and f.first_seen_at > now() - make_interval(days => (rules->>'min_days')::int)
        and progress->f.card_id->>'state' = 'mastered'
        and not exists (select 1 from lexica_card_editions e where e.user_id = uid and e.card_id = f.card_id)
    ), '{}'::jsonb),
    'config', jsonb_build_object(
      'mint_odds', lexica_cfg('mint_odds'), 'pity', lexica_cfg('pity'), 'mint_rules', rules,
      'boxes', lexica_cfg('boxes'), 'box_table', lexica_cfg('box_table'), 'prices', lexica_cfg('prices'))
  );
end;
$$;

create or replace function public.lexica_mint(p_card_id text)
returns jsonb language plpgsql security definer set search_path = public as $$
declare
  uid uuid := auth.uid();
  w lexica_wallet;
  rules jsonb := lexica_cfg('mint_rules');
  progress jsonb;
  seen timestamptz;
  edition text;
  serial int;
  box int := 0;
begin
  if uid is null then raise exception 'not signed in' using errcode = '28000'; end if;
  w := lexica_wallet_for_update(uid);
  if exists (select 1 from lexica_card_editions where user_id = uid and card_id = p_card_id) then
    raise exception 'already minted' using errcode = 'P0001';
  end if;
  if w.mints_today >= (rules->>'max_per_day')::int then
    raise exception 'daily mint limit reached' using errcode = 'P0001';
  end if;
  progress := coalesce(lexica_backup_progress(uid), '{}'::jsonb)->p_card_id;
  select first_seen_at into seen from lexica_card_first_seen where user_id = uid and card_id = p_card_id;
  if progress->>'state' is distinct from 'mastered'
     or coalesce((progress->>'reviewCount')::int, 0) < (rules->>'min_reviews')::int
     or seen is null
     or seen > now() - make_interval(days => (rules->>'min_days')::int) then
    raise exception 'card not ready to mint' using errcode = 'P0001';
  end if;

  edition := lexica_roll_edition(uid, true);
  if edition = 'legendary' then serial := nextval('lexica_legendary_serial'); end if;
  insert into lexica_card_editions (user_id, card_id, edition, serial) values (uid, p_card_id, edition, serial);
  update lexica_wallet set mints_total = mints_total + 1, mints_today = mints_today + 1
  where user_id = uid returning * into w;
  insert into lexica_wallet_ledger (user_id, kind, delta, ref)
  values (uid, 'mint', jsonb_build_object('edition', edition, 'serial', serial), p_card_id);

  if w.mints_total % (rules->>'box_every')::int = 0 then
    box := lexica_grant_boxes(uid, 1, 'box:mints', w.mints_total::text);
  end if;
  return jsonb_build_object('card_id', p_card_id, 'edition', edition, 'serial', serial, 'boxes_earned', box);
end;
$$;

-- Rewards the app reports (daily goal, set complete, ghost streak, streak
-- milestones). Each (kind, ref) pays once; boxes respect the daily cap.
create or replace function public.lexica_claim(p_kind text, p_ref text)
returns jsonb language plpgsql security definer set search_path = public as $$
declare
  uid uuid := auth.uid();
  amount int := (lexica_cfg('boxes')->>p_kind)::int;
  granted int;
begin
  if uid is null then raise exception 'not signed in' using errcode = '28000'; end if;
  if amount is null or p_kind not in ('daily_goal','set_complete','ghost_streak','streak_7','streak_30','streak_100') then
    raise exception 'unknown reward' using errcode = 'P0001';
  end if;
  if p_ref is null or char_length(p_ref) > 60 then raise exception 'bad ref' using errcode = 'P0001'; end if;
  -- Date-based rewards only for today (no back-filling past days).
  if p_kind in ('daily_goal','ghost_streak') and p_ref <> lexica_today()::text then
    raise exception 'reward is for today only' using errcode = 'P0001';
  end if;
  if exists (select 1 from lexica_wallet_ledger where user_id = uid and kind = 'claim:' || p_kind and ref = p_ref) then
    return jsonb_build_object('claimed', false, 'boxes', 0);
  end if;
  granted := lexica_grant_boxes(uid, amount, 'claim:' || p_kind, p_ref);
  return jsonb_build_object('claimed', true, 'boxes', granted, 'pending', amount - granted);
end;
$$;

create or replace function public.lexica_open_box()
returns jsonb language plpgsql security definer set search_path = public as $$
declare
  uid uuid := auth.uid();
  w lexica_wallet;
  prices jsonb := lexica_cfg('prices');
  entry jsonb;
  r numeric := random();
  acc numeric := 0;
  item text;
  amount int;
begin
  if uid is null then raise exception 'not signed in' using errcode = '28000'; end if;
  w := lexica_wallet_for_update(uid);
  if w.boxes < 1 then raise exception 'no boxes' using errcode = 'P0001'; end if;
  for entry in select * from jsonb_array_elements(lexica_cfg('box_table')) loop
    acc := acc + (entry->>'p')::numeric;
    if r < acc then item := entry->>'item'; amount := (entry->>'amount')::int; exit; end if;
  end loop;
  if item is null then item := 'dust'; amount := 20; end if;
  -- A freeze when already holding the maximum becomes dust instead.
  if item = 'freeze' and w.streak_freezes >= (prices->>'freeze_max')::int then
    item := 'dust'; amount := (prices->>'freeze_full_dust')::int;
  end if;
  update lexica_wallet set
    boxes = boxes - 1,
    dust = dust + case when item = 'dust' then amount else 0 end,
    streak_freezes = streak_freezes + case when item = 'freeze' then amount else 0 end,
    reroll_tickets = reroll_tickets + case when item = 'ticket' then amount else 0 end
  where user_id = uid returning * into w;
  insert into lexica_wallet_ledger (user_id, kind, delta) values (uid, 'box_opened', jsonb_build_object('item', item, 'amount', amount));
  return jsonb_build_object('item', item, 'amount', amount, 'wallet', to_jsonb(w) - 'user_id');
end;
$$;

create or replace function public.lexica_buy_ticket()
returns jsonb language plpgsql security definer set search_path = public as $$
declare
  uid uuid := auth.uid();
  w lexica_wallet;
  price int := (lexica_cfg('prices')->>'ticket')::int;
begin
  if uid is null then raise exception 'not signed in' using errcode = '28000'; end if;
  w := lexica_wallet_for_update(uid);
  if w.dust < price then raise exception 'not enough dust' using errcode = 'P0001'; end if;
  update lexica_wallet set dust = dust - price, reroll_tickets = reroll_tickets + 1 where user_id = uid returning * into w;
  insert into lexica_wallet_ledger (user_id, kind, delta) values (uid, 'ticket_bought', jsonb_build_object('dust', -price, 'tickets', 1));
  return jsonb_build_object('wallet', to_jsonb(w) - 'user_id');
end;
$$;

-- Rerolls a minted card with a ticket. A result that is not better keeps the
-- old edition and refunds some dust; an edition is never lost.
create or replace function public.lexica_reroll(p_card_id text)
returns jsonb language plpgsql security definer set search_path = public as $$
declare
  uid uuid := auth.uid();
  w lexica_wallet;
  prices jsonb := lexica_cfg('prices');
  current_edition text;
  rolled text;
  refund int := 0;
  kept boolean;
  new_serial int;
begin
  if uid is null then raise exception 'not signed in' using errcode = '28000'; end if;
  w := lexica_wallet_for_update(uid);
  select edition into current_edition from lexica_card_editions where user_id = uid and card_id = p_card_id for update;
  if current_edition is null then raise exception 'card not minted' using errcode = 'P0001'; end if;
  if current_edition = 'legendary' then raise exception 'already legendary' using errcode = 'P0001'; end if;
  if w.reroll_tickets < 1 then raise exception 'no reroll tickets' using errcode = 'P0001'; end if;

  rolled := lexica_roll_edition(uid, false);
  kept := lexica_edition_rank(rolled) <= lexica_edition_rank(current_edition);
  if kept then
    refund := case rolled when 'common' then (prices->>'refund_common')::int when 'silver' then (prices->>'refund_silver')::int else 0 end;
    update lexica_card_editions set rerolls = rerolls + 1 where user_id = uid and card_id = p_card_id;
  else
    if rolled = 'legendary' then new_serial := nextval('lexica_legendary_serial'); end if;
    update lexica_card_editions set edition = rolled, serial = new_serial, rerolls = rerolls + 1
    where user_id = uid and card_id = p_card_id;
  end if;
  update lexica_wallet set reroll_tickets = reroll_tickets - 1, dust = dust + refund where user_id = uid returning * into w;
  insert into lexica_wallet_ledger (user_id, kind, delta, ref)
  values (uid, 'reroll', jsonb_build_object('rolled', rolled, 'kept', kept, 'refund', refund), p_card_id);
  return jsonb_build_object(
    'rolled', rolled, 'kept', kept, 'refund', refund,
    'edition', case when kept then current_edition else rolled end, 'serial', new_serial,
    'wallet', to_jsonb(w) - 'user_id');
end;
$$;

-- Common → Silver for dust. Holo and Legendary only come from rolls.
create or replace function public.lexica_upgrade(p_card_id text)
returns jsonb language plpgsql security definer set search_path = public as $$
declare
  uid uuid := auth.uid();
  w lexica_wallet;
  price int := (lexica_cfg('prices')->>'upgrade_silver')::int;
  current_edition text;
begin
  if uid is null then raise exception 'not signed in' using errcode = '28000'; end if;
  w := lexica_wallet_for_update(uid);
  select edition into current_edition from lexica_card_editions where user_id = uid and card_id = p_card_id for update;
  if current_edition is distinct from 'common' then raise exception 'only common cards can be upgraded' using errcode = 'P0001'; end if;
  if w.dust < price then raise exception 'not enough dust' using errcode = 'P0001'; end if;
  update lexica_card_editions set edition = 'silver' where user_id = uid and card_id = p_card_id;
  update lexica_wallet set dust = dust - price where user_id = uid returning * into w;
  insert into lexica_wallet_ledger (user_id, kind, delta, ref) values (uid, 'upgrade', jsonb_build_object('dust', -price, 'edition', 'silver'), p_card_id);
  return jsonb_build_object('edition', 'silver', 'wallet', to_jsonb(w) - 'user_id');
end;
$$;

-- Spends a streak freeze to cover one missed day (the app calls this when it
-- finds a gap of exactly one day). Each missed date can be covered once.
create or replace function public.lexica_use_freeze(p_missed_date date)
returns jsonb language plpgsql security definer set search_path = public as $$
declare
  uid uuid := auth.uid();
  w lexica_wallet;
begin
  if uid is null then raise exception 'not signed in' using errcode = '28000'; end if;
  if p_missed_date <> lexica_today() - 1 then raise exception 'only yesterday can be covered' using errcode = 'P0001'; end if;
  w := lexica_wallet_for_update(uid);
  if exists (select 1 from lexica_wallet_ledger where user_id = uid and kind = 'freeze_used' and ref = p_missed_date::text) then
    return jsonb_build_object('used', true, 'wallet', to_jsonb(w) - 'user_id');
  end if;
  if w.streak_freezes < 1 then return jsonb_build_object('used', false, 'wallet', to_jsonb(w) - 'user_id'); end if;
  update lexica_wallet set streak_freezes = streak_freezes - 1 where user_id = uid returning * into w;
  insert into lexica_wallet_ledger (user_id, kind, delta, ref) values (uid, 'freeze_used', '{"freezes": -1}', p_missed_date::text);
  return jsonb_build_object('used', true, 'wallet', to_jsonb(w) - 'user_id');
end;
$$;

-- Internal helpers are not callable from the app.
revoke all on function public.lexica_wallet_for_update(uuid) from public, anon, authenticated;
revoke all on function public.lexica_grant_boxes(uuid, int, text, text) from public, anon, authenticated;
revoke all on function public.lexica_roll_edition(uuid, boolean) from public, anon, authenticated;
revoke all on function public.lexica_backup_progress(uuid) from public, anon, authenticated;
revoke all on function public.lexica_cfg(text) from public, anon, authenticated;

do $$
declare f text;
begin
  foreach f in array array[
    'lexica_engagement_state()', 'lexica_mint(text)', 'lexica_claim(text, text)', 'lexica_open_box()',
    'lexica_buy_ticket()', 'lexica_reroll(text)', 'lexica_upgrade(text)', 'lexica_use_freeze(date)']
  loop
    execute format('revoke all on function public.%s from public, anon', f);
    execute format('grant execute on function public.%s to authenticated', f);
  end loop;
end $$;


-- ============================================================
-- apps/lexica/supabase/migration_engagement_lucky.sql
-- ============================================================

-- Lucky cards in the swipe deck: about one card in 15 pays a small reward
-- when the learner marks it as known. Which cards are lucky is decided here
-- (a hash of user, card and day), so the app can show the badge before the
-- swipe but cannot choose its own lucky cards. Capped per day.
-- Requires migration_engagement.sql. Idempotent.

insert into public.lexica_engagement_config (key, value) values
  ('lucky', '{"one_in": 15, "daily_cap": 5, "table": [{"item":"dust","amount":15,"p":0.70},{"item":"dust","amount":30,"p":0.20},{"item":"dust","amount":50,"p":0.08},{"item":"box","amount":1,"p":0.02}]}')
on conflict (key) do nothing;

create or replace function public.lexica_is_lucky(p_user uuid, p_card_id text, p_day date)
returns boolean language sql stable as $$
  select ('x' || substr(md5(p_user::text || ':' || p_card_id || ':' || p_day::text), 1, 8))::bit(32)::bigint
         % greatest(1, coalesce((select (value->>'one_in')::int from lexica_engagement_config where key = 'lucky'), 15)) = 0;
$$;

-- Which of these cards are lucky for the caller today.
create or replace function public.lexica_lucky_cards(p_card_ids text[])
returns text[] language plpgsql stable security definer set search_path = public as $$
declare
  uid uuid := auth.uid();
begin
  if uid is null then return '{}'; end if;
  return coalesce((
    select array_agg(id) from unnest(p_card_ids[1:50]) as id
    where char_length(id) <= 40 and lexica_is_lucky(uid, id, lexica_today())
  ), '{}');
end;
$$;

-- Pays a lucky card once per day, within the daily cap.
create or replace function public.lexica_lucky_claim(p_card_id text)
returns jsonb language plpgsql security definer set search_path = public as $$
declare
  uid uuid := auth.uid();
  cfg jsonb := lexica_cfg('lucky');
  today_claims int;
  entry jsonb;
  r numeric := random();
  acc numeric := 0;
  item text;
  amount int;
  granted int;
  w lexica_wallet;
begin
  if uid is null then raise exception 'not signed in' using errcode = '28000'; end if;
  if not lexica_is_lucky(uid, p_card_id, lexica_today()) then
    return jsonb_build_object('paid', false, 'reason', 'not lucky');
  end if;
  w := lexica_wallet_for_update(uid);
  if exists (select 1 from lexica_wallet_ledger where user_id = uid and kind = 'lucky'
             and ref = p_card_id and (at at time zone 'Asia/Ho_Chi_Minh')::date = lexica_today()) then
    return jsonb_build_object('paid', false, 'reason', 'already paid');
  end if;
  select count(*) into today_claims from lexica_wallet_ledger
  where user_id = uid and kind = 'lucky' and (at at time zone 'Asia/Ho_Chi_Minh')::date = lexica_today();
  if today_claims >= (cfg->>'daily_cap')::int then
    return jsonb_build_object('paid', false, 'reason', 'daily cap');
  end if;

  for entry in select * from jsonb_array_elements(cfg->'table') loop
    acc := acc + (entry->>'p')::numeric;
    if r < acc then item := entry->>'item'; amount := (entry->>'amount')::int; exit; end if;
  end loop;
  if item is null then item := 'dust'; amount := 15; end if;

  -- A box over today's cap waits for tomorrow (lexica_grant_boxes).
  if item = 'box' then
    granted := lexica_grant_boxes(uid, amount, 'lucky_box', p_card_id);
  end if;
  if item = 'dust' then
    update lexica_wallet set dust = dust + amount where user_id = uid;
  end if;
  insert into lexica_wallet_ledger (user_id, kind, delta, ref)
  values (uid, 'lucky', jsonb_build_object('item', item, 'amount', amount), p_card_id);
  return jsonb_build_object('paid', true, 'item', item, 'amount', amount);
end;
$$;

revoke all on function public.lexica_is_lucky(uuid, text, date) from public, anon, authenticated;
revoke all on function public.lexica_lucky_cards(text[]) from public, anon;
grant execute on function public.lexica_lucky_cards(text[]) to authenticated;
revoke all on function public.lexica_lucky_claim(text) from public, anon;
grant execute on function public.lexica_lucky_claim(text) to authenticated;


-- ============================================================
-- apps/lexica/supabase/migration_engagement_lucky_status.sql
-- ============================================================

-- Lucky cards, with the number of lucky rewards left today
-- (docs/LEXICA_FEEDBACK_TASKS.md T6): once the daily cap is used up the app
-- stops showing the "may mắn" badge instead of promising a gift it can't pay.
-- Requires migration_engagement_lucky.sql. Idempotent.

create or replace function public.lexica_lucky_status(p_card_ids text[])
returns jsonb language plpgsql stable security definer set search_path = public as $$
declare
  uid uuid := auth.uid();
  cap int := coalesce((lexica_cfg('lucky')->>'daily_cap')::int, 5);
  used int;
begin
  if uid is null then return jsonb_build_object('cards', '[]'::jsonb, 'remaining', 0); end if;
  select count(*) into used from lexica_wallet_ledger
  where user_id = uid and kind = 'lucky' and (at at time zone 'Asia/Ho_Chi_Minh')::date = lexica_today();
  return jsonb_build_object(
    'remaining', greatest(0, cap - used),
    'cards', case when used >= cap then '[]'::jsonb else to_jsonb(coalesce((
      select array_agg(id) from unnest(p_card_ids[1:50]) as id
      where char_length(id) <= 40 and lexica_is_lucky(uid, id, lexica_today())
    ), '{}')) end
  );
end;
$$;

revoke all on function public.lexica_lucky_status(text[]) from public, anon;
grant execute on function public.lexica_lucky_status(text[]) to authenticated;


-- ============================================================
-- apps/lexica/supabase/migration_engagement_review_dust.sql
-- ============================================================

-- Review points turn into Bụi (docs/LEXICA_FEEDBACK_TASKS.md T3): at the end of
-- a review session the banked points of "Liều hay Dừng" are exchanged at
-- 10 points = 1 Bụi, at most 30 Bụi a day. The points are counted on the
-- device, so the daily cap is what keeps this honest.
-- Requires migration_engagement.sql. Idempotent.

insert into public.lexica_engagement_config (key, value) values
  ('review_dust', '{"points_per_dust": 10, "daily_cap": 30}')
on conflict (key) do nothing;

create or replace function public.lexica_review_dust(p_points int)
returns jsonb language plpgsql security definer set search_path = public as $$
declare
  uid uuid := auth.uid();
  cfg jsonb := lexica_cfg('review_dust');
  per int := greatest(1, coalesce((cfg->>'points_per_dust')::int, 10));
  cap int := coalesce((cfg->>'daily_cap')::int, 30);
  earned int;
  pay int;
  w lexica_wallet;
begin
  if uid is null then raise exception 'not signed in' using errcode = '28000'; end if;
  if p_points is null or p_points < 0 or p_points > 100000 then
    raise exception 'bad points' using errcode = '22023';
  end if;
  w := lexica_wallet_for_update(uid);
  select coalesce(sum((delta->>'dust')::int), 0) into earned from lexica_wallet_ledger
  where user_id = uid and kind = 'review_dust'
    and (at at time zone 'Asia/Ho_Chi_Minh')::date = lexica_today();
  pay := greatest(0, least(p_points / per, cap - earned));
  if pay > 0 then
    update lexica_wallet set dust = dust + pay where user_id = uid returning * into w;
    insert into lexica_wallet_ledger (user_id, kind, delta)
    values (uid, 'review_dust', jsonb_build_object('dust', pay, 'points', p_points));
  end if;
  return jsonb_build_object('dust', pay, 'earned_today', earned + pay, 'cap', cap, 'wallet', to_jsonb(w));
end;
$$;

revoke all on function public.lexica_review_dust(int) from public, anon;
grant execute on function public.lexica_review_dust(int) to authenticated;


-- ============================================================
-- apps/lexica/supabase/migration_classes.sql
-- ============================================================

-- Lexica for English centers (docs/LEXICA_DIRECTION.md, "Trung tâm"): a
-- teacher makes a class and shares its code, assigns words by lesson, and
-- sees each student's four numbers and streak; students join by code and
-- report their own numbers. Every read and write goes through the security
-- definer functions below; the tables have RLS on and no client policies.
-- Requires migration_engagement.sql (lexica_today). Safe to re-run.

create table if not exists lexica_orgs (
  id uuid primary key default gen_random_uuid(),
  name text not null check (char_length(name) between 2 and 80),
  seats int not null default 30 check (seats between 1 and 5000),
  owner_id uuid not null references auth.users(id) on delete cascade,
  created_at timestamptz not null default now()
);

create table if not exists lexica_org_members (
  org_id uuid not null references lexica_orgs(id) on delete cascade,
  user_id uuid not null references auth.users(id) on delete cascade,
  role text not null check (role in ('admin','teacher')),
  primary key (org_id, user_id)
);

create table if not exists lexica_classes (
  id uuid primary key default gen_random_uuid(),
  org_id uuid references lexica_orgs(id) on delete set null,
  teacher_id uuid not null references auth.users(id) on delete cascade,
  name text not null check (char_length(name) between 2 and 80),
  code text not null unique,
  branch text not null default 'cert' check (branch in ('cert','talk')),
  level text check (level in ('beginner','intermediate','advanced','expert')),
  archived boolean not null default false,
  created_at timestamptz not null default now()
);

create table if not exists lexica_class_members (
  class_id uuid not null references lexica_classes(id) on delete cascade,
  user_id uuid not null references auth.users(id) on delete cascade,
  display_name text not null check (char_length(display_name) between 1 and 40),
  joined_at timestamptz not null default now(),
  primary key (class_id, user_id)
);

create table if not exists lexica_class_assignments (
  id uuid primary key default gen_random_uuid(),
  class_id uuid not null references lexica_classes(id) on delete cascade,
  title text not null check (char_length(title) between 1 and 80),
  card_ids text[] not null,
  missing_words text[] not null default '{}',
  created_by uuid references auth.users(id),
  created_at timestamptz not null default now()
);
create index if not exists lexica_class_assignments_class_idx on lexica_class_assignments (class_id, created_at);

-- Latest numbers a student reported, and one snapshot per day for the weekly report.
create table if not exists lexica_class_progress (
  class_id uuid not null references lexica_classes(id) on delete cascade,
  user_id uuid not null references auth.users(id) on delete cascade,
  counts jsonb not null default '{}',     -- {hieu,nho,gap,dung} over all words
  assigned jsonb not null default '{}',   -- {hieu,nho,gap,dung,total} over this class's assigned words
  streak int not null default 0,
  last_active date,
  updated_at timestamptz not null default now(),
  primary key (class_id, user_id)
);

create table if not exists lexica_class_progress_daily (
  class_id uuid not null references lexica_classes(id) on delete cascade,
  user_id uuid not null references auth.users(id) on delete cascade,
  date date not null,
  counts jsonb not null,
  assigned jsonb not null default '{}',
  primary key (class_id, user_id, date)
);

-- Words a teacher assigned that Lexica has no card for yet; Studio writes them.
create table if not exists lexica_word_requests (
  id uuid primary key default gen_random_uuid(),
  class_id uuid references lexica_classes(id) on delete set null,
  word text not null check (char_length(word) between 1 and 60),
  status text not null default 'open' check (status in ('open','done')),
  created_at timestamptz not null default now()
);
create index if not exists lexica_word_requests_status_idx on lexica_word_requests (status, created_at);

alter table lexica_orgs enable row level security;
alter table lexica_org_members enable row level security;
alter table lexica_classes enable row level security;
alter table lexica_class_members enable row level security;
alter table lexica_class_assignments enable row level security;
alter table lexica_class_progress enable row level security;
alter table lexica_class_progress_daily enable row level security;
alter table lexica_word_requests enable row level security;

-- Studio editors read and close word requests (is_studio_editor from migration_studio.sql).
drop policy if exists "lexica_word_requests editors" on lexica_word_requests;
create policy "lexica_word_requests editors" on lexica_word_requests
  for all using (is_studio_editor()) with check (is_studio_editor());

-- ── helpers ─────────────────────────────────────────────────────────────

create or replace function public.lexica_class_code()
returns text language plpgsql volatile set search_path = public as $$
declare
  alphabet text := 'ABCDEFGHJKLMNPQRSTUVWXYZ23456789';
  c text;
begin
  loop
    c := '';
    for i in 1..6 loop
      c := c || substr(alphabet, 1 + floor(random() * length(alphabet))::int, 1);
    end loop;
    exit when not exists (select 1 from lexica_classes where code = c);
  end loop;
  return c;
end;
$$;

-- The teacher of a class, or an admin of its center.
create or replace function public.lexica_can_teach(p_class uuid)
returns boolean language sql stable security definer set search_path = public as $$
  select exists (
    select 1 from lexica_classes c
    where c.id = p_class and (
      c.teacher_id = auth.uid()
      or exists (select 1 from lexica_org_members m where m.org_id = c.org_id and m.user_id = auth.uid() and m.role = 'admin')
    )
  );
$$;

-- Clamp a client-sent step count object to four non-negative ints (and total when given).
create or replace function public.lexica_counts(p jsonb)
returns jsonb language sql immutable as $$
  select jsonb_strip_nulls(jsonb_build_object(
    'hieu', least(greatest(coalesce((p->>'hieu')::int, 0), 0), 100000),
    'nho', least(greatest(coalesce((p->>'nho')::int, 0), 0), 100000),
    'gap', least(greatest(coalesce((p->>'gap')::int, 0), 0), 100000),
    'dung', least(greatest(coalesce((p->>'dung')::int, 0), 0), 100000),
    'total', case when p ? 'total' then least(greatest((p->>'total')::int, 0), 100000) end
  ));
$$;

-- ── centers ─────────────────────────────────────────────────────────────

create or replace function public.lexica_org_create(p_name text)
returns jsonb language plpgsql volatile security definer set search_path = public as $$
declare
  uid uuid := auth.uid();
  oid uuid;
begin
  if uid is null then raise exception 'not signed in'; end if;
  insert into lexica_orgs (name, owner_id) values (trim(p_name), uid) returning id into oid;
  insert into lexica_org_members (org_id, user_id, role) values (oid, uid, 'admin');
  return jsonb_build_object('id', oid);
end;
$$;

-- An admin adds a teacher by the email they signed in to Lexica with.
create or replace function public.lexica_org_add_teacher(p_org uuid, p_email text)
returns jsonb language plpgsql volatile security definer set search_path = public, auth as $$
declare
  target uuid;
begin
  if not exists (select 1 from lexica_org_members where org_id = p_org and user_id = auth.uid() and role = 'admin') then
    raise exception 'not an admin';
  end if;
  select id into target from auth.users where lower(email) = lower(trim(p_email)) limit 1;
  if target is null then raise exception 'no such user'; end if;
  insert into lexica_org_members (org_id, user_id, role) values (p_org, target, 'teacher')
  on conflict (org_id, user_id) do nothing;
  return jsonb_build_object('ok', true);
end;
$$;

-- An admin's view of the center: seats and each class with its averages.
create or replace function public.lexica_org_overview(p_org uuid)
returns jsonb language plpgsql stable security definer set search_path = public as $$
begin
  if not exists (select 1 from lexica_org_members where org_id = p_org and user_id = auth.uid() and role = 'admin') then
    raise exception 'not an admin';
  end if;
  return (
    select jsonb_build_object(
      'id', o.id,
      'name', o.name,
      'seats', o.seats,
      'used', (select count(distinct m.user_id) from lexica_class_members m join lexica_classes c on c.id = m.class_id where c.org_id = o.id and not c.archived),
      'teachers', (select count(*) from lexica_org_members where org_id = o.id),
      'classes', coalesce((
        select jsonb_agg(jsonb_build_object(
          'id', c.id,
          'name', c.name,
          'members', (select count(*) from lexica_class_members where class_id = c.id),
          'avg_nho', (select round(avg((p.counts->>'nho')::int)) from lexica_class_progress p where p.class_id = c.id),
          'avg_dung', (select round(avg((p.counts->>'dung')::int)) from lexica_class_progress p where p.class_id = c.id),
          'active_week', (select count(*) from lexica_class_progress p where p.class_id = c.id and p.last_active >= lexica_today() - 6)
        ) order by c.created_at)
        from lexica_classes c where c.org_id = o.id and not c.archived
      ), '[]'::jsonb)
    )
    from lexica_orgs o where o.id = p_org
  );
end;
$$;

-- ── classes ─────────────────────────────────────────────────────────────

create or replace function public.lexica_class_create(p_name text, p_branch text default 'cert', p_level text default null, p_org uuid default null)
returns jsonb language plpgsql volatile security definer set search_path = public as $$
declare
  uid uuid := auth.uid();
  cid uuid;
  c text;
begin
  if uid is null then raise exception 'not signed in'; end if;
  if p_org is not null and not exists (select 1 from lexica_org_members where org_id = p_org and user_id = uid) then
    raise exception 'not in this center';
  end if;
  c := lexica_class_code();
  insert into lexica_classes (org_id, teacher_id, name, code, branch, level)
  values (p_org, uid, trim(p_name), c, coalesce(p_branch, 'cert'), p_level)
  returning id into cid;
  return jsonb_build_object('id', cid, 'code', c);
end;
$$;

create or replace function public.lexica_class_join(p_code text, p_display_name text)
returns jsonb language plpgsql volatile security definer set search_path = public as $$
declare
  uid uuid := auth.uid();
  cls lexica_classes;
  seats int;
  used int;
begin
  if uid is null then raise exception 'not signed in'; end if;
  select * into cls from lexica_classes where code = upper(trim(p_code)) and not archived;
  if cls.id is null then raise exception 'no such class'; end if;
  -- The class's teacher (or the center's admin) teaches it; they do not join it as a student.
  if lexica_can_teach(cls.id) then raise exception 'own class'; end if;
  if exists (select 1 from lexica_class_members where class_id = cls.id and user_id = uid) then
    update lexica_class_members set display_name = trim(p_display_name) where class_id = cls.id and user_id = uid;
    return jsonb_build_object('class_id', cls.id, 'name', cls.name, 'branch', cls.branch, 'level', cls.level);
  end if;
  -- Seats: a center's limit across its classes; a teacher on their own gets 60 per class.
  if cls.org_id is not null then
    select o.seats into seats from lexica_orgs o where o.id = cls.org_id;
    select count(distinct m.user_id) into used from lexica_class_members m join lexica_classes c on c.id = m.class_id
    where c.org_id = cls.org_id and not c.archived;
    if used >= seats and not exists (
      select 1 from lexica_class_members m join lexica_classes c on c.id = m.class_id where c.org_id = cls.org_id and m.user_id = uid
    ) then raise exception 'no seats'; end if;
  elsif (select count(*) from lexica_class_members where class_id = cls.id) >= 60 then
    raise exception 'no seats';
  end if;
  insert into lexica_class_members (class_id, user_id, display_name) values (cls.id, uid, trim(p_display_name));
  return jsonb_build_object('class_id', cls.id, 'name', cls.name, 'branch', cls.branch, 'level', cls.level);
end;
$$;

create or replace function public.lexica_class_leave(p_class uuid)
returns jsonb language sql volatile security definer set search_path = public as $$
  with gone as (delete from lexica_class_members where class_id = p_class and user_id = auth.uid() returning 1),
       prog as (delete from lexica_class_progress where class_id = p_class and user_id = auth.uid() returning 1)
  select jsonb_build_object('left', (select count(*) from gone) > 0);
$$;

-- Classes the user is in or teaches, with their assignments (the code only for teachers).
create or replace function public.lexica_my_classes()
returns jsonb language sql stable security definer set search_path = public as $$
  select coalesce(jsonb_agg(item order by item->>'created_at'), '[]'::jsonb) from (
    select jsonb_build_object(
      'id', c.id,
      'name', c.name,
      'branch', c.branch,
      'level', c.level,
      'org_id', c.org_id,
      'created_at', c.created_at,
      'role', case when c.teacher_id = auth.uid() or lexica_can_teach(c.id) then 'teacher' else 'student' end,
      'code', case when c.teacher_id = auth.uid() or lexica_can_teach(c.id) then c.code end,
      'members', (select count(*) from lexica_class_members where class_id = c.id),
      'assignments', coalesce((
        select jsonb_agg(jsonb_build_object('id', a.id, 'title', a.title, 'card_ids', a.card_ids, 'missing_words', a.missing_words, 'created_at', a.created_at) order by a.created_at desc)
        from lexica_class_assignments a where a.class_id = c.id
      ), '[]'::jsonb)
    ) as item
    from lexica_classes c
    where not c.archived and (
      c.teacher_id = auth.uid()
      or lexica_can_teach(c.id)
      or exists (select 1 from lexica_class_members m where m.class_id = c.id and m.user_id = auth.uid())
    )
  ) t;
$$;

create or replace function public.lexica_my_orgs()
returns jsonb language sql stable security definer set search_path = public as $$
  select coalesce(jsonb_agg(jsonb_build_object('id', o.id, 'name', o.name, 'role', m.role, 'seats', o.seats)), '[]'::jsonb)
  from lexica_org_members m join lexica_orgs o on o.id = m.org_id
  where m.user_id = auth.uid();
$$;

-- A student's own numbers, sent by the app. p_assigned: {classId: {hieu,nho,gap,dung,total}}.
create or replace function public.lexica_class_report(p_counts jsonb, p_streak int, p_assigned jsonb default '{}'::jsonb)
returns jsonb language plpgsql volatile security definer set search_path = public as $$
declare
  uid uuid := auth.uid();
  m record;
  n int := 0;
  mine jsonb;
begin
  if uid is null then return jsonb_build_object('classes', 0); end if;
  for m in select class_id from lexica_class_members where user_id = uid loop
    mine := lexica_counts(coalesce(p_assigned -> (m.class_id::text), '{}'::jsonb));
    insert into lexica_class_progress (class_id, user_id, counts, assigned, streak, last_active, updated_at)
    values (m.class_id, uid, lexica_counts(p_counts), mine, least(greatest(coalesce(p_streak, 0), 0), 10000), lexica_today(), now())
    on conflict (class_id, user_id) do update set
      counts = excluded.counts, assigned = excluded.assigned, streak = excluded.streak,
      last_active = excluded.last_active, updated_at = now();
    insert into lexica_class_progress_daily (class_id, user_id, date, counts, assigned)
    values (m.class_id, uid, lexica_today(), lexica_counts(p_counts), mine)
    on conflict (class_id, user_id, date) do update set counts = excluded.counts, assigned = excluded.assigned;
    n := n + 1;
  end loop;
  return jsonb_build_object('classes', n);
end;
$$;

-- The teacher's board: each student's numbers now and a week ago, streak, days since active.
create or replace function public.lexica_class_board(p_class uuid)
returns jsonb language plpgsql stable security definer set search_path = public as $$
begin
  if not lexica_can_teach(p_class) then raise exception 'not the teacher'; end if;
  return (
    select jsonb_build_object(
      'class', (select jsonb_build_object('id', c.id, 'name', c.name, 'code', c.code, 'branch', c.branch, 'level', c.level) from lexica_classes c where c.id = p_class),
      'students', coalesce(jsonb_agg(jsonb_build_object(
        'user_id', m.user_id,
        'name', m.display_name,
        'joined_at', m.joined_at,
        'counts', coalesce(p.counts, '{}'::jsonb),
        'assigned', coalesce(p.assigned, '{}'::jsonb),
        'streak', coalesce(p.streak, 0),
        'last_active', p.last_active,
        'inactive_days', case when p.last_active is null then null else lexica_today() - p.last_active end,
        'week_ago', (
          select d.counts from lexica_class_progress_daily d
          where d.class_id = p_class and d.user_id = m.user_id and d.date <= lexica_today() - 7
          order by d.date desc limit 1
        ),
        'week_first', (
          select d.counts from lexica_class_progress_daily d
          where d.class_id = p_class and d.user_id = m.user_id and d.date > lexica_today() - 7
          order by d.date asc limit 1
        )
      ) order by m.display_name), '[]'::jsonb)
    )
    from lexica_class_members m
    left join lexica_class_progress p on p.class_id = m.class_id and p.user_id = m.user_id
    where m.class_id = p_class
  );
end;
$$;

-- Students rank by words they can use (Dùng), not by game points.
create or replace function public.lexica_class_leaderboard(p_class uuid)
returns jsonb language plpgsql stable security definer set search_path = public as $$
begin
  if not (lexica_can_teach(p_class) or exists (select 1 from lexica_class_members where class_id = p_class and user_id = auth.uid())) then
    raise exception 'not in this class';
  end if;
  return (
    select coalesce(jsonb_agg(jsonb_build_object('name', m.display_name, 'dung', coalesce((p.counts->>'dung')::int, 0), 'nho', coalesce((p.counts->>'nho')::int, 0), 'me', m.user_id = auth.uid())
      order by coalesce((p.counts->>'dung')::int, 0) desc, coalesce((p.counts->>'nho')::int, 0) desc, m.display_name), '[]'::jsonb)
    from lexica_class_members m
    left join lexica_class_progress p on p.class_id = m.class_id and p.user_id = m.user_id
    where m.class_id = p_class
  );
end;
$$;

-- Words for a lesson: card ids Lexica has, and the words it has no card for yet (sent to Studio).
create or replace function public.lexica_class_assign(p_class uuid, p_title text, p_card_ids text[], p_missing text[] default '{}')
returns jsonb language plpgsql volatile security definer set search_path = public as $$
declare
  aid uuid;
  ids text[] := (select coalesce(array_agg(distinct x), '{}') from unnest(p_card_ids[1:200]) x where char_length(x) between 1 and 40);
  missing text[] := (select coalesce(array_agg(distinct lower(trim(x))), '{}') from unnest(p_missing[1:200]) x where char_length(trim(x)) between 1 and 60);
begin
  if not lexica_can_teach(p_class) then raise exception 'not the teacher'; end if;
  if coalesce(array_length(ids, 1), 0) = 0 and coalesce(array_length(missing, 1), 0) = 0 then raise exception 'no words'; end if;
  insert into lexica_class_assignments (class_id, title, card_ids, missing_words, created_by)
  values (p_class, trim(p_title), ids, missing, auth.uid()) returning id into aid;
  insert into lexica_word_requests (class_id, word) select p_class, w from unnest(missing) w;
  return jsonb_build_object('id', aid, 'cards', coalesce(array_length(ids, 1), 0), 'missing', coalesce(array_length(missing, 1), 0));
end;
$$;

create or replace function public.lexica_class_unassign(p_assignment uuid)
returns jsonb language plpgsql volatile security definer set search_path = public as $$
declare
  cid uuid;
begin
  select class_id into cid from lexica_class_assignments where id = p_assignment;
  if cid is null or not lexica_can_teach(cid) then raise exception 'not the teacher'; end if;
  delete from lexica_class_assignments where id = p_assignment;
  return jsonb_build_object('ok', true);
end;
$$;

do $$
declare f text;
begin
  foreach f in array array[
    'lexica_org_create(text)', 'lexica_org_add_teacher(uuid, text)', 'lexica_org_overview(uuid)',
    'lexica_class_create(text, text, text, uuid)', 'lexica_class_join(text, text)', 'lexica_class_leave(uuid)',
    'lexica_my_classes()', 'lexica_my_orgs()', 'lexica_class_report(jsonb, int, jsonb)', 'lexica_class_board(uuid)',
    'lexica_class_leaderboard(uuid)', 'lexica_class_assign(uuid, text, text[], text[])', 'lexica_class_unassign(uuid)'
  ] loop
    execute format('revoke all on function public.%s from public, anon', f);
    execute format('grant execute on function public.%s to authenticated', f);
  end loop;
  revoke all on function public.lexica_can_teach(uuid) from public, anon;
  revoke all on function public.lexica_class_code() from public, anon, authenticated;
end $$;

-- The API sees the new functions without waiting for its schema cache.
notify pgrst, 'reload schema';


-- ============================================================
-- apps/lexica/supabase/migration_classes_v2.sql
-- ============================================================

-- Lexica for classes, v2 (Claude Doc "Lexica Lớp học — thiết kế"): the
-- teacher app on its own subdomain, entered only by invitation.
--
-- - lexica_staff: system admins (create centers, grant independent teachers)
--   and independent teachers (classes outside any center).
-- - lexica_invites: one-use links with a role, a center and an expiry.
-- - Classes: leaderboard on/off (off by default); assignments with a due
--   date and a mode ('only': the lesson's words alone; 'mixed'); a private
--   note per student; per-word progress on assigned words.
--
-- Requires migration_classes.sql. Safe to re-run. After the first run, make
-- yourself the system admin once (your Lexica sign-in email):
--   insert into lexica_staff (user_id, role)
--   select id, 'admin' from auth.users where lower(email) = lower('you@example.com')
--   on conflict (user_id) do update set role = 'admin';

create table if not exists lexica_staff (
  user_id uuid primary key references auth.users(id) on delete cascade,
  role text not null check (role in ('admin','indie')),
  granted_by uuid references auth.users(id),
  created_at timestamptz not null default now()
);

create table if not exists lexica_invites (
  token text primary key,
  kind text not null check (kind in ('org_admin','org_teacher','indie')),
  org_id uuid references lexica_orgs(id) on delete cascade,
  note text check (char_length(note) <= 80),
  created_by uuid not null references auth.users(id) on delete cascade,
  expires_at timestamptz not null,
  used_by uuid references auth.users(id) on delete set null,
  used_at timestamptz,
  created_at timestamptz not null default now()
);
create index if not exists lexica_invites_org_idx on lexica_invites (org_id, created_at desc);

alter table lexica_staff enable row level security;
alter table lexica_invites enable row level security;

alter table lexica_classes add column if not exists leaderboard boolean not null default false;
alter table lexica_class_assignments add column if not exists due_on date;
alter table lexica_class_assignments add column if not exists mode text not null default 'only';
do $$ begin
  alter table lexica_class_assignments add constraint lexica_class_assignments_mode check (mode in ('only','mixed'));
exception when duplicate_object then null; end $$;
alter table lexica_class_members add column if not exists note text;
do $$ begin
  alter table lexica_class_members add constraint lexica_class_members_note check (char_length(note) <= 500);
exception when duplicate_object then null; end $$;
-- Per assigned word, the furthest step: 1 Hiểu … 4 Dùng, 5 used in real life (Đời).
alter table lexica_class_progress add column if not exists words jsonb not null default '{}';

-- ── who is who ──────────────────────────────────────────────────────────

create or replace function public.lexica_is_admin()
returns boolean language sql stable security definer set search_path = public as $$
  select exists (select 1 from lexica_staff where user_id = auth.uid() and role = 'admin');
$$;

create or replace function public.lexica_is_org_admin(p_org uuid)
returns boolean language sql stable security definer set search_path = public as $$
  select lexica_is_admin() or exists (
    select 1 from lexica_org_members where org_id = p_org and user_id = auth.uid() and role = 'admin'
  );
$$;

-- The teacher of a class, an admin of its center, or a system admin (support).
create or replace function public.lexica_can_teach(p_class uuid)
returns boolean language sql stable security definer set search_path = public as $$
  select exists (
    select 1 from lexica_classes c
    where c.id = p_class and (
      c.teacher_id = auth.uid()
      or exists (select 1 from lexica_org_members m where m.org_id = c.org_id and m.user_id = auth.uid() and m.role = 'admin')
      or exists (select 1 from lexica_staff s where s.user_id = auth.uid() and s.role = 'admin')
    )
  );
$$;

-- What the teacher app may show this person; empty roles = only the "contact us" page.
create or replace function public.lexica_whoami()
returns jsonb language sql stable security definer set search_path = public, auth as $$
  select jsonb_build_object(
    'email', (select email from auth.users where id = auth.uid()),
    'admin', exists (select 1 from lexica_staff where user_id = auth.uid() and role = 'admin'),
    'indie', exists (select 1 from lexica_staff where user_id = auth.uid() and role in ('indie','admin')),
    'orgs', coalesce((
      select jsonb_agg(jsonb_build_object('id', o.id, 'name', o.name, 'role', m.role, 'seats', o.seats) order by o.name)
      from lexica_org_members m join lexica_orgs o on o.id = m.org_id where m.user_id = auth.uid()
    ), '[]'::jsonb)
  );
$$;

-- ── centers (system admin) ──────────────────────────────────────────────

create or replace function public.lexica_org_create(p_name text)
returns jsonb language plpgsql volatile security definer set search_path = public as $$
declare
  oid uuid;
begin
  if not lexica_is_admin() then raise exception 'not an admin'; end if;
  insert into lexica_orgs (name, owner_id) values (trim(p_name), auth.uid()) returning id into oid;
  return jsonb_build_object('id', oid);
end;
$$;

create or replace function public.lexica_org_update(p_org uuid, p_name text default null, p_seats int default null)
returns jsonb language plpgsql volatile security definer set search_path = public as $$
begin
  if p_seats is not null and not lexica_is_admin() then raise exception 'not an admin'; end if;
  if p_name is not null and not lexica_is_org_admin(p_org) then raise exception 'not an admin'; end if;
  update lexica_orgs set name = coalesce(nullif(trim(p_name), ''), name), seats = coalesce(p_seats, seats) where id = p_org;
  return jsonb_build_object('ok', true);
end;
$$;

-- Every center with its seats, and the independent teachers.
create or replace function public.lexica_admin_overview()
returns jsonb language plpgsql stable security definer set search_path = public, auth as $$
begin
  if not lexica_is_admin() then raise exception 'not an admin'; end if;
  return jsonb_build_object(
    'orgs', coalesce((
      select jsonb_agg(jsonb_build_object(
        'id', o.id, 'name', o.name, 'seats', o.seats, 'created_at', o.created_at,
        'used', (select count(distinct m.user_id) from lexica_class_members m join lexica_classes c on c.id = m.class_id where c.org_id = o.id and not c.archived),
        'admins', (select count(*) from lexica_org_members where org_id = o.id and role = 'admin'),
        'teachers', (select count(*) from lexica_org_members where org_id = o.id),
        'classes', (select count(*) from lexica_classes where org_id = o.id and not archived)
      ) order by o.created_at desc)
      from lexica_orgs o
    ), '[]'::jsonb),
    'indie', coalesce((
      select jsonb_agg(jsonb_build_object(
        'user_id', s.user_id, 'email', u.email, 'since', s.created_at,
        'classes', (select count(*) from lexica_classes c where c.teacher_id = s.user_id and c.org_id is null and not c.archived)
      ) order by s.created_at desc)
      from lexica_staff s join auth.users u on u.id = s.user_id where s.role = 'indie'
    ), '[]'::jsonb)
  );
end;
$$;

create or replace function public.lexica_indie_revoke(p_user uuid)
returns jsonb language plpgsql volatile security definer set search_path = public as $$
begin
  if not lexica_is_admin() then raise exception 'not an admin'; end if;
  delete from lexica_staff where user_id = p_user and role = 'indie';
  return jsonb_build_object('ok', true);
end;
$$;

-- ── invitations ─────────────────────────────────────────────────────────

-- org_admin and indie: system admin only; org_teacher: an admin of that center.
create or replace function public.lexica_invite_create(p_kind text, p_org uuid default null, p_note text default null, p_days int default 7)
returns jsonb language plpgsql volatile security definer set search_path = public as $$
declare
  -- Two random UUIDs: 244 random bits, no extension needed.
  t text := replace(gen_random_uuid()::text || gen_random_uuid()::text, '-', '');
begin
  if auth.uid() is null then raise exception 'not signed in'; end if;
  if p_kind = 'indie' then
    if not lexica_is_admin() then raise exception 'not an admin'; end if;
    p_org := null;
  elsif p_kind = 'org_admin' then
    if not lexica_is_admin() or p_org is null then raise exception 'not an admin'; end if;
  elsif p_kind = 'org_teacher' then
    if p_org is null or not lexica_is_org_admin(p_org) then raise exception 'not an admin'; end if;
  else
    raise exception 'bad invite';
  end if;
  insert into lexica_invites (token, kind, org_id, note, created_by, expires_at)
  values (t, p_kind, p_org, nullif(trim(p_note), ''), auth.uid(), now() + make_interval(days => least(greatest(coalesce(p_days, 7), 1), 30)));
  return jsonb_build_object('token', t);
end;
$$;

-- What an invitation is for, shown before signing in. Says nothing about who sent it.
create or replace function public.lexica_invite_info(p_token text)
returns jsonb language sql stable security definer set search_path = public as $$
  select coalesce((
    select jsonb_build_object(
      'kind', i.kind,
      'org', (select name from lexica_orgs where id = i.org_id),
      'valid', i.used_at is null and i.expires_at > now()
    )
    from lexica_invites i where i.token = p_token
  ), jsonb_build_object('valid', false));
$$;

create or replace function public.lexica_invite_accept(p_token text)
returns jsonb language plpgsql volatile security definer set search_path = public as $$
declare
  uid uuid := auth.uid();
  inv lexica_invites;
begin
  if uid is null then raise exception 'not signed in'; end if;
  select * into inv from lexica_invites where token = p_token for update;
  if inv.token is null or inv.used_at is not null or inv.expires_at <= now() then raise exception 'invite expired'; end if;
  if inv.kind = 'indie' then
    insert into lexica_staff (user_id, role, granted_by) values (uid, 'indie', inv.created_by)
    on conflict (user_id) do nothing;
  else
    insert into lexica_org_members (org_id, user_id, role)
    values (inv.org_id, uid, case when inv.kind = 'org_admin' then 'admin' else 'teacher' end)
    on conflict (org_id, user_id) do update set role = case when excluded.role = 'admin' then 'admin' else lexica_org_members.role end;
  end if;
  update lexica_invites set used_by = uid, used_at = now() where token = p_token;
  return jsonb_build_object('kind', inv.kind, 'org_id', inv.org_id);
end;
$$;

-- Invitations still open, for whoever may make them.
create or replace function public.lexica_invites_open(p_org uuid default null)
returns jsonb language plpgsql stable security definer set search_path = public as $$
begin
  if (p_org is null and not lexica_is_admin()) or (p_org is not null and not lexica_is_org_admin(p_org)) then
    raise exception 'not an admin';
  end if;
  return coalesce((
    select jsonb_agg(jsonb_build_object('token', i.token, 'kind', i.kind, 'note', i.note, 'expires_at', i.expires_at, 'org', (select name from lexica_orgs where id = i.org_id)) order by i.created_at desc)
    from lexica_invites i
    where i.used_at is null and i.expires_at > now()
      and ((p_org is null and i.kind in ('indie','org_admin')) or i.org_id = p_org)
  ), '[]'::jsonb);
end;
$$;

create or replace function public.lexica_invite_revoke(p_token text)
returns jsonb language plpgsql volatile security definer set search_path = public as $$
declare
  inv lexica_invites;
begin
  select * into inv from lexica_invites where token = p_token;
  if inv.token is null then return jsonb_build_object('ok', true); end if;
  if not (lexica_is_admin() or (inv.org_id is not null and lexica_is_org_admin(inv.org_id))) then raise exception 'not an admin'; end if;
  delete from lexica_invites where token = p_token and used_at is null;
  return jsonb_build_object('ok', true);
end;
$$;

-- ── a center (its admins) ───────────────────────────────────────────────

create or replace function public.lexica_org_overview(p_org uuid)
returns jsonb language plpgsql stable security definer set search_path = public, auth as $$
begin
  if not lexica_is_org_admin(p_org) then raise exception 'not an admin'; end if;
  return (
    select jsonb_build_object(
      'id', o.id,
      'name', o.name,
      'seats', o.seats,
      'used', (select count(distinct m.user_id) from lexica_class_members m join lexica_classes c on c.id = m.class_id where c.org_id = o.id and not c.archived),
      'people', coalesce((
        select jsonb_agg(jsonb_build_object(
          'user_id', m.user_id, 'email', u.email, 'role', m.role,
          'classes', (select count(*) from lexica_classes c where c.org_id = o.id and c.teacher_id = m.user_id and not c.archived)
        ) order by m.role, u.email)
        from lexica_org_members m join auth.users u on u.id = m.user_id where m.org_id = o.id
      ), '[]'::jsonb),
      'classes', coalesce((
        select jsonb_agg(jsonb_build_object(
          'id', c.id,
          'name', c.name,
          'teacher', (select email from auth.users where id = c.teacher_id),
          'members', (select count(*) from lexica_class_members where class_id = c.id),
          'avg_nho', (select round(avg((p.counts->>'nho')::int)) from lexica_class_progress p where p.class_id = c.id),
          'avg_dung', (select round(avg((p.counts->>'dung')::int)) from lexica_class_progress p where p.class_id = c.id),
          'active_week', (select count(*) from lexica_class_progress p where p.class_id = c.id and p.last_active >= lexica_today() - 6)
        ) order by c.created_at)
        from lexica_classes c where c.org_id = o.id and not c.archived
      ), '[]'::jsonb)
    )
    from lexica_orgs o where o.id = p_org
  );
end;
$$;

-- A center admin removes a teacher (their classes stay, now taught by the center's admins).
create or replace function public.lexica_org_remove_member(p_org uuid, p_user uuid)
returns jsonb language plpgsql volatile security definer set search_path = public as $$
begin
  if not lexica_is_org_admin(p_org) then raise exception 'not an admin'; end if;
  if p_user = auth.uid() then raise exception 'not yourself'; end if;
  delete from lexica_org_members where org_id = p_org and user_id = p_user;
  return jsonb_build_object('ok', true);
end;
$$;

-- ── classes ─────────────────────────────────────────────────────────────

-- In a center: any of its members. Outside one: independent teachers and system admins.
create or replace function public.lexica_class_create(p_name text, p_branch text default 'cert', p_level text default null, p_org uuid default null)
returns jsonb language plpgsql volatile security definer set search_path = public as $$
declare
  uid uuid := auth.uid();
  cid uuid;
  c text;
begin
  if uid is null then raise exception 'not signed in'; end if;
  if p_org is not null then
    if not exists (select 1 from lexica_org_members where org_id = p_org and user_id = uid) then raise exception 'not in this center'; end if;
  elsif not exists (select 1 from lexica_staff where user_id = uid) then
    raise exception 'not a teacher';
  end if;
  c := lexica_class_code();
  insert into lexica_classes (org_id, teacher_id, name, code, branch, level)
  values (p_org, uid, trim(p_name), c, coalesce(p_branch, 'cert'), p_level)
  returning id into cid;
  return jsonb_build_object('id', cid, 'code', c);
end;
$$;

create or replace function public.lexica_class_update(p_class uuid, p_name text default null, p_branch text default null, p_level text default null, p_leaderboard boolean default null, p_archived boolean default null)
returns jsonb language plpgsql volatile security definer set search_path = public as $$
begin
  if not lexica_can_teach(p_class) then raise exception 'not the teacher'; end if;
  update lexica_classes set
    name = coalesce(nullif(trim(p_name), ''), name),
    branch = coalesce(p_branch, branch),
    level = case when p_level = '' then null else coalesce(p_level, level) end,
    leaderboard = coalesce(p_leaderboard, leaderboard),
    archived = coalesce(p_archived, archived)
  where id = p_class;
  return jsonb_build_object('ok', true);
end;
$$;

-- A new code (the old one stops working: for a code that leaked).
create or replace function public.lexica_class_new_code(p_class uuid)
returns jsonb language plpgsql volatile security definer set search_path = public as $$
declare
  c text := lexica_class_code();
begin
  if not lexica_can_teach(p_class) then raise exception 'not the teacher'; end if;
  update lexica_classes set code = c where id = p_class;
  return jsonb_build_object('code', c);
end;
$$;

-- Classes the user is in or teaches, with their assignments (the code only for teachers).
create or replace function public.lexica_my_classes()
returns jsonb language sql stable security definer set search_path = public as $$
  select coalesce(jsonb_agg(item order by item->>'created_at'), '[]'::jsonb) from (
    select jsonb_build_object(
      'id', c.id,
      'name', c.name,
      'branch', c.branch,
      'level', c.level,
      'org_id', c.org_id,
      'org', (select name from lexica_orgs where id = c.org_id),
      'created_at', c.created_at,
      'leaderboard', c.leaderboard,
      'role', case when lexica_can_teach(c.id) and not exists (select 1 from lexica_class_members m where m.class_id = c.id and m.user_id = auth.uid()) then 'teacher' else 'student' end,
      'code', case when lexica_can_teach(c.id) then c.code end,
      'members', (select count(*) from lexica_class_members where class_id = c.id),
      'assignments', coalesce((
        select jsonb_agg(jsonb_build_object('id', a.id, 'title', a.title, 'card_ids', a.card_ids, 'missing_words', a.missing_words, 'created_at', a.created_at, 'due_on', a.due_on, 'mode', a.mode) order by a.created_at desc)
        from lexica_class_assignments a where a.class_id = c.id
      ), '[]'::jsonb)
    ) as item
    from lexica_classes c
    where not c.archived and (
      c.teacher_id = auth.uid()
      or lexica_can_teach(c.id) and (c.teacher_id = auth.uid() or exists (select 1 from lexica_org_members om where om.org_id = c.org_id and om.user_id = auth.uid()))
      or exists (select 1 from lexica_class_members m where m.class_id = c.id and m.user_id = auth.uid())
    )
  ) t;
$$;

-- A student's own numbers, with per-word steps on assigned words. p_words: {cardId: 1..5}.
create or replace function public.lexica_class_report(p_counts jsonb, p_streak int, p_assigned jsonb, p_words jsonb)
returns jsonb language plpgsql volatile security definer set search_path = public as $$
declare
  uid uuid := auth.uid();
  m record;
  n int := 0;
  mine jsonb;
  words jsonb;
begin
  if uid is null then return jsonb_build_object('classes', 0); end if;
  for m in select class_id from lexica_class_members where user_id = uid loop
    mine := lexica_counts(coalesce(p_assigned -> (m.class_id::text), '{}'::jsonb));
    -- Only this class's assigned words, steps clamped to 1..5.
    select coalesce(jsonb_object_agg(k, least(greatest((v #>> '{}')::int, 0), 5)), '{}'::jsonb) into words
    from jsonb_each(coalesce(p_words, '{}'::jsonb)) as e(k, v)
    where jsonb_typeof(v) = 'number'
      and exists (select 1 from lexica_class_assignments a where a.class_id = m.class_id and k = any(a.card_ids));
    insert into lexica_class_progress (class_id, user_id, counts, assigned, streak, last_active, updated_at, words)
    values (m.class_id, uid, lexica_counts(p_counts), mine, least(greatest(coalesce(p_streak, 0), 0), 10000), lexica_today(), now(), words)
    on conflict (class_id, user_id) do update set
      counts = excluded.counts, assigned = excluded.assigned, streak = excluded.streak,
      last_active = excluded.last_active, updated_at = now(), words = excluded.words;
    insert into lexica_class_progress_daily (class_id, user_id, date, counts, assigned)
    values (m.class_id, uid, lexica_today(), lexica_counts(p_counts), mine)
    on conflict (class_id, user_id, date) do update set counts = excluded.counts, assigned = excluded.assigned;
    n := n + 1;
  end loop;
  return jsonb_build_object('classes', n);
end;
$$;

-- Steps now count "Đời" (words used in real life) too.
create or replace function public.lexica_counts(p jsonb)
returns jsonb language sql immutable as $$
  select jsonb_strip_nulls(jsonb_build_object(
    'hieu', least(greatest(coalesce((p->>'hieu')::int, 0), 0), 100000),
    'nho', least(greatest(coalesce((p->>'nho')::int, 0), 0), 100000),
    'gap', least(greatest(coalesce((p->>'gap')::int, 0), 0), 100000),
    'dung', least(greatest(coalesce((p->>'dung')::int, 0), 0), 100000),
    'doi', case when p ? 'doi' then least(greatest((p->>'doi')::int, 0), 100000) end,
    'total', case when p ? 'total' then least(greatest((p->>'total')::int, 0), 100000) end
  ));
$$;

-- The teacher's board: the class, its assignments, each student with numbers, steps per assigned word, note.
create or replace function public.lexica_class_board(p_class uuid)
returns jsonb language plpgsql stable security definer set search_path = public as $$
begin
  if not lexica_can_teach(p_class) then raise exception 'not the teacher'; end if;
  return (
    select jsonb_build_object(
      'class', (
        select jsonb_build_object('id', c.id, 'name', c.name, 'code', c.code, 'branch', c.branch, 'level', c.level,
          'leaderboard', c.leaderboard, 'org_id', c.org_id, 'created_at', c.created_at,
          'org', (select name from lexica_orgs where id = c.org_id))
        from lexica_classes c where c.id = p_class
      ),
      'assignments', coalesce((
        select jsonb_agg(jsonb_build_object('id', a.id, 'title', a.title, 'card_ids', a.card_ids, 'missing_words', a.missing_words, 'created_at', a.created_at, 'due_on', a.due_on, 'mode', a.mode) order by a.created_at desc)
        from lexica_class_assignments a where a.class_id = p_class
      ), '[]'::jsonb),
      'students', coalesce((
        select jsonb_agg(jsonb_build_object(
          'user_id', m.user_id,
          'name', m.display_name,
          'joined_at', m.joined_at,
          'note', m.note,
          'counts', coalesce(p.counts, '{}'::jsonb),
          'assigned', coalesce(p.assigned, '{}'::jsonb),
          'words', coalesce(p.words, '{}'::jsonb),
          'streak', coalesce(p.streak, 0),
          'last_active', p.last_active,
          'inactive_days', case when p.last_active is null then null else lexica_today() - p.last_active end,
          'week_ago', (
            select d.counts from lexica_class_progress_daily d
            where d.class_id = p_class and d.user_id = m.user_id and d.date <= lexica_today() - 7
            order by d.date desc limit 1
          ),
          'week_first', (
            select d.counts from lexica_class_progress_daily d
            where d.class_id = p_class and d.user_id = m.user_id and d.date > lexica_today() - 7
            order by d.date asc limit 1
          ),
          'days', (
            select coalesce(jsonb_agg(d.date order by d.date), '[]'::jsonb) from lexica_class_progress_daily d
            where d.class_id = p_class and d.user_id = m.user_id and d.date > lexica_today() - 30
          )
        ) order by m.display_name)
        from lexica_class_members m
        left join lexica_class_progress p on p.class_id = m.class_id and p.user_id = m.user_id
        where m.class_id = p_class
      ), '[]'::jsonb)
    )
  );
end;
$$;

-- Students see the ranking only when the teacher turned it on.
create or replace function public.lexica_class_leaderboard(p_class uuid)
returns jsonb language plpgsql stable security definer set search_path = public as $$
begin
  if not (lexica_can_teach(p_class) or exists (select 1 from lexica_class_members where class_id = p_class and user_id = auth.uid())) then
    raise exception 'not in this class';
  end if;
  if not lexica_can_teach(p_class) and not (select leaderboard from lexica_classes where id = p_class) then
    return '[]'::jsonb;
  end if;
  return (
    select coalesce(jsonb_agg(jsonb_build_object('name', m.display_name, 'dung', coalesce((p.counts->>'dung')::int, 0), 'nho', coalesce((p.counts->>'nho')::int, 0), 'me', m.user_id = auth.uid())
      order by coalesce((p.counts->>'dung')::int, 0) desc, coalesce((p.counts->>'nho')::int, 0) desc, m.display_name), '[]'::jsonb)
    from lexica_class_members m
    left join lexica_class_progress p on p.class_id = m.class_id and p.user_id = m.user_id
    where m.class_id = p_class
  );
end;
$$;

create or replace function public.lexica_class_assign(p_class uuid, p_title text, p_card_ids text[], p_missing text[], p_due date, p_mode text)
returns jsonb language plpgsql volatile security definer set search_path = public as $$
declare
  aid uuid;
  ids text[] := (select coalesce(array_agg(distinct x), '{}') from unnest(p_card_ids[1:200]) x where char_length(x) between 1 and 40);
  missing text[] := (select coalesce(array_agg(distinct lower(trim(x))), '{}') from unnest(p_missing[1:200]) x where char_length(trim(x)) between 1 and 60);
begin
  if not lexica_can_teach(p_class) then raise exception 'not the teacher'; end if;
  if coalesce(array_length(ids, 1), 0) = 0 and coalesce(array_length(missing, 1), 0) = 0 then raise exception 'no words'; end if;
  insert into lexica_class_assignments (class_id, title, card_ids, missing_words, created_by, due_on, mode)
  values (p_class, trim(p_title), ids, missing, auth.uid(), p_due, case when p_mode = 'mixed' then 'mixed' else 'only' end) returning id into aid;
  insert into lexica_word_requests (class_id, word) select p_class, w from unnest(missing) w;
  return jsonb_build_object('id', aid, 'cards', coalesce(array_length(ids, 1), 0), 'missing', coalesce(array_length(missing, 1), 0));
end;
$$;

create or replace function public.lexica_class_assignment_update(p_assignment uuid, p_title text default null, p_due date default null, p_clear_due boolean default false, p_mode text default null)
returns jsonb language plpgsql volatile security definer set search_path = public as $$
declare
  cid uuid;
begin
  select class_id into cid from lexica_class_assignments where id = p_assignment;
  if cid is null or not lexica_can_teach(cid) then raise exception 'not the teacher'; end if;
  update lexica_class_assignments set
    title = coalesce(nullif(trim(p_title), ''), title),
    due_on = case when p_clear_due then null else coalesce(p_due, due_on) end,
    mode = case when p_mode in ('only','mixed') then p_mode else mode end
  where id = p_assignment;
  return jsonb_build_object('ok', true);
end;
$$;

create or replace function public.lexica_class_member_update(p_class uuid, p_user uuid, p_note text default null, p_remove boolean default false)
returns jsonb language plpgsql volatile security definer set search_path = public as $$
begin
  if not lexica_can_teach(p_class) then raise exception 'not the teacher'; end if;
  if p_remove then
    delete from lexica_class_progress where class_id = p_class and user_id = p_user;
    delete from lexica_class_members where class_id = p_class and user_id = p_user;
  else
    update lexica_class_members set note = nullif(trim(p_note), '') where class_id = p_class and user_id = p_user;
  end if;
  return jsonb_build_object('ok', true);
end;
$$;

do $$
declare f text;
begin
  foreach f in array array[
    'lexica_whoami()', 'lexica_org_create(text)', 'lexica_org_update(uuid, text, int)', 'lexica_admin_overview()',
    'lexica_indie_revoke(uuid)', 'lexica_invite_create(text, uuid, text, int)', 'lexica_invite_accept(text)',
    'lexica_invites_open(uuid)', 'lexica_invite_revoke(text)', 'lexica_org_overview(uuid)', 'lexica_org_remove_member(uuid, uuid)',
    'lexica_class_create(text, text, text, uuid)', 'lexica_class_update(uuid, text, text, text, boolean, boolean)',
    'lexica_class_new_code(uuid)', 'lexica_my_classes()', 'lexica_class_report(jsonb, int, jsonb, jsonb)',
    'lexica_class_board(uuid)', 'lexica_class_leaderboard(uuid)',
    'lexica_class_assign(uuid, text, text[], text[], date, text)', 'lexica_class_assignment_update(uuid, text, date, boolean, text)',
    'lexica_class_member_update(uuid, uuid, text, boolean)'
  ] loop
    execute format('revoke all on function public.%s from public, anon', f);
    execute format('grant execute on function public.%s to authenticated', f);
  end loop;
  -- Shown on the invitation page before signing in.
  revoke all on function public.lexica_invite_info(text) from public;
  grant execute on function public.lexica_invite_info(text) to anon, authenticated;
  revoke all on function public.lexica_is_admin() from public, anon;
  revoke all on function public.lexica_is_org_admin(uuid) from public, anon;
end $$;

notify pgrst, 'reload schema';


-- ============================================================
-- apps/oratio/supabase/migration_2026_10_security.sql
-- ============================================================

-- ============================================
-- Oratio: security and data fixes (2026-10-18)
-- Run in the Supabase SQL Editor after every other app's SQL (Lexica and
-- Cortex share this project and public.profiles). Safe to run again; run it
-- again after any Lexica migration that touches profiles policies.
--
-- What it does:
--   1. Profiles: a user reads only their own row (email included). Other
--      users' public fields come from the public_profiles view.
--   2. Users can edit only username, avatar, country, native language and
--      target band. Stats and band are written by the server only.
--   3. match_queue, matches and session_feedback are written by the server
--      only (the app's server actions use the service role).
--   4. A user can't be in two open matches at once.
--   5. A session counts (sessions, minutes, streak) only when both people
--      joined the call and it lasted at least a minute. Old declines that
--      were counted are repaired.
--   6. Band from peer feedback needs 3 different raters in 30 days.
--   7. leaderboard() for weekly / monthly / all-time ranking.
--   8. expire_stale_matches() closes abandoned matches (optional cron).
-- ============================================

-- --------------------------------------------
-- 0. Columns the app uses
-- --------------------------------------------
ALTER TABLE public.matches ADD COLUMN IF NOT EXISTS swap_requested_by UUID REFERENCES auth.users(id) DEFAULT NULL;
-- When each person asked to join the call; started_at is set once both did
ALTER TABLE public.matches ADD COLUMN IF NOT EXISTS user1_joined_at TIMESTAMPTZ;
ALTER TABLE public.matches ADD COLUMN IF NOT EXISTS user2_joined_at TIMESTAMPTZ;
-- Bumped by the in-call screen; an active match with no activity is abandoned
ALTER TABLE public.matches ADD COLUMN IF NOT EXISTS last_activity_at TIMESTAMPTZ;
-- Realtime needs the full row to deliver UPDATE events through RLS
ALTER TABLE public.matches REPLICA IDENTITY FULL;

-- --------------------------------------------
-- 1. Profiles: own row only, public fields through a view
-- --------------------------------------------
-- Every policy that let any signed-in user read every row (Oratio's old one
-- and Lexica's study-buddy ones) goes; buddies read nicknames from the view.
DROP POLICY IF EXISTS "Profiles are viewable by everyone" ON public.profiles;
DROP POLICY IF EXISTS "Authenticated users can read profiles" ON public.profiles;
DROP POLICY IF EXISTS "profiles_select" ON public.profiles;
DROP POLICY IF EXISTS "Users can view their own profile" ON public.profiles;
CREATE POLICY "Users can view their own profile"
    ON public.profiles FOR SELECT
    USING (auth.uid() = id);

-- The view runs with its owner's rights, so it shows every profile but only
-- these columns (no email). New columns go at the end (CREATE OR REPLACE
-- VIEW can only append).
ALTER TABLE public.profiles ADD COLUMN IF NOT EXISTS nickname TEXT NOT NULL DEFAULT 'Anonymous';
CREATE OR REPLACE VIEW public.public_profiles AS
    SELECT id, username, avatar_url, current_band, total_sessions, total_minutes,
           current_streak, longest_streak, nickname
    FROM public.profiles;
REVOKE ALL ON public.public_profiles FROM PUBLIC, anon;
GRANT SELECT ON public.public_profiles TO authenticated;

-- --------------------------------------------
-- 2. Profiles: users edit only descriptive fields
-- --------------------------------------------
-- Profiles are created by the on_auth_user_created trigger. Lexica may still
-- insert its own row with a nickname (profiles_insert policy: id = auth.uid()),
-- so only those columns can be inserted; stats keep their defaults.
DROP POLICY IF EXISTS "Users can insert their own profile" ON public.profiles;
REVOKE INSERT, UPDATE, DELETE ON public.profiles FROM anon, authenticated;
GRANT INSERT (id, username, nickname) ON public.profiles TO authenticated;
GRANT UPDATE (username, nickname, avatar_url, native_language, country, target_band) ON public.profiles TO authenticated;

DO $$
BEGIN
    IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'profiles_username_length') THEN
        ALTER TABLE public.profiles
            ADD CONSTRAINT profiles_username_length CHECK (char_length(username) BETWEEN 1 AND 40) NOT VALID;
    END IF;
END $$;

-- --------------------------------------------
-- 3. Queue, matches, feedback: read your own, write through the server
-- --------------------------------------------
DROP POLICY IF EXISTS "Users can insert themselves into queue" ON public.match_queue;
DROP POLICY IF EXISTS "Users can update their own queue entry" ON public.match_queue;
DROP POLICY IF EXISTS "Users can delete their own queue entry" ON public.match_queue;
REVOKE INSERT, UPDATE, DELETE ON public.match_queue FROM anon, authenticated;

DROP POLICY IF EXISTS "Users can update matches they are part of" ON public.matches;
REVOKE INSERT, UPDATE, DELETE ON public.matches FROM anon, authenticated;

DROP POLICY IF EXISTS "Users can insert feedback for matches they participated in" ON public.session_feedback;
DROP POLICY IF EXISTS "Users can update their own feedback" ON public.session_feedback;
REVOKE INSERT, UPDATE, DELETE ON public.session_feedback FROM anon, authenticated;

DO $$
BEGIN
    IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'session_feedback_comments_length') THEN
        ALTER TABLE public.session_feedback
            ADD CONSTRAINT session_feedback_comments_length CHECK (comments IS NULL OR char_length(comments) <= 1000) NOT VALID;
    END IF;
END $$;

REVOKE INSERT, UPDATE, DELETE ON public.ielts_questions FROM anon, authenticated;

-- --------------------------------------------
-- 4. One open match per user
-- --------------------------------------------
CREATE OR REPLACE FUNCTION public.prevent_double_match()
RETURNS TRIGGER
LANGUAGE plpgsql
SET search_path = public
AS $$
DECLARE
    k1 INTEGER := hashtext(NEW.user1_id::text);
    k2 INTEGER := hashtext(NEW.user2_id::text);
BEGIN
    -- Lock both users in a fixed order so concurrent inserts wait for each other
    PERFORM pg_advisory_xact_lock(LEAST(k1, k2));
    PERFORM pg_advisory_xact_lock(GREATEST(k1, k2));

    IF EXISTS (
        SELECT 1 FROM public.matches
        WHERE status IN ('pending', 'active')
          AND (user1_id IN (NEW.user1_id, NEW.user2_id) OR user2_id IN (NEW.user1_id, NEW.user2_id))
    ) THEN
        RAISE EXCEPTION 'A user in this match already has an open match' USING ERRCODE = 'unique_violation';
    END IF;
    RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS before_match_insert ON public.matches;
CREATE TRIGGER before_match_insert
    BEFORE INSERT ON public.matches
    FOR EACH ROW EXECUTE FUNCTION public.prevent_double_match();

-- --------------------------------------------
-- 5. Session stats: only calls both people joined, at least a minute
-- --------------------------------------------
CREATE OR REPLACE FUNCTION public.update_user_stats_after_match()
RETURNS TRIGGER
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
    seconds NUMERIC;
    minutes INTEGER;
BEGIN
    IF NEW.status = 'finished' AND OLD.status IS DISTINCT FROM 'finished' AND NEW.started_at IS NOT NULL THEN
        seconds := EXTRACT(EPOCH FROM (COALESCE(NEW.ended_at, NOW()) - NEW.started_at));
        IF seconds < 60 THEN
            RETURN NEW;
        END IF;
        -- A full mock test is about 30 minutes; cap so a forgotten tab can't add hours
        minutes := LEAST(90, ROUND(seconds / 60))::INTEGER;

        UPDATE public.profiles
        SET
            total_sessions = COALESCE(total_sessions, 0) + 1,
            total_minutes = COALESCE(total_minutes, 0) + minutes,
            last_practice_date = CURRENT_DATE,
            current_streak = CASE
                WHEN last_practice_date = CURRENT_DATE - 1 THEN COALESCE(current_streak, 0) + 1
                WHEN last_practice_date = CURRENT_DATE THEN GREATEST(COALESCE(current_streak, 0), 1)
                ELSE 1
            END,
            longest_streak = GREATEST(COALESCE(longest_streak, 0),
                CASE
                    WHEN last_practice_date = CURRENT_DATE - 1 THEN COALESCE(current_streak, 0) + 1
                    WHEN last_practice_date = CURRENT_DATE THEN GREATEST(COALESCE(current_streak, 0), 1)
                    ELSE 1
                END
            )
        WHERE id IN (NEW.user1_id, NEW.user2_id);
    END IF;

    RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS on_match_finished ON public.matches;
CREATE TRIGGER on_match_finished
    AFTER UPDATE ON public.matches
    FOR EACH ROW EXECUTE FUNCTION public.update_user_stats_after_match();

-- Repair: declines used to be saved as 'finished' with no started_at, which
-- counted a session and set total_minutes to NULL. Mark them cancelled and
-- recount sessions and minutes from real calls. (The trigger above ignores
-- the change to 'cancelled'.)
UPDATE public.matches
SET status = 'cancelled'
WHERE status = 'finished' AND started_at IS NULL;

WITH calls AS (
    SELECT user1_id AS u, EXTRACT(EPOCH FROM (ended_at - started_at)) AS s
    FROM public.matches WHERE status = 'finished' AND started_at IS NOT NULL AND ended_at IS NOT NULL
    UNION ALL
    SELECT user2_id, EXTRACT(EPOCH FROM (ended_at - started_at))
    FROM public.matches WHERE status = 'finished' AND started_at IS NOT NULL AND ended_at IS NOT NULL
),
per_user AS (
    SELECT u, COUNT(*) AS n, SUM(LEAST(90, ROUND(s / 60)))::INTEGER AS mins
    FROM calls WHERE s >= 60 GROUP BY u
)
UPDATE public.profiles p
SET total_sessions = COALESCE((SELECT n FROM per_user WHERE u = p.id), 0),
    total_minutes = COALESCE((SELECT mins FROM per_user WHERE u = p.id), 0);

ALTER TABLE public.profiles ALTER COLUMN total_minutes SET DEFAULT 0;
ALTER TABLE public.profiles ALTER COLUMN total_sessions SET DEFAULT 0;

-- --------------------------------------------
-- 6. Band from peer feedback: 3 different raters, rounded to .5
-- --------------------------------------------
CREATE OR REPLACE FUNCTION public.update_current_band_from_feedback()
RETURNS TRIGGER
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
    raters INTEGER;
    avg_band NUMERIC;
BEGIN
    IF NEW.scores IS NOT NULL AND (NEW.scores->>'overall') IS NOT NULL THEN
        -- One vote per rater (their own average), so one partner can't move a band alone
        SELECT COUNT(*), AVG(r) INTO raters, avg_band
        FROM (
            SELECT from_user_id, AVG((scores->>'overall')::NUMERIC) AS r
            FROM public.session_feedback
            WHERE to_user_id = NEW.to_user_id
              AND scores IS NOT NULL
              AND (scores->>'overall') IS NOT NULL
              AND created_at >= NOW() - INTERVAL '30 days'
            GROUP BY from_user_id
        ) t;

        IF raters >= 3 THEN
            UPDATE public.profiles
            SET current_band = LEAST(9, GREATEST(1, ROUND(avg_band * 2) / 2))
            WHERE id = NEW.to_user_id;
        END IF;
    END IF;

    RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS on_feedback_received ON public.session_feedback;
CREATE TRIGGER on_feedback_received
    AFTER INSERT ON public.session_feedback
    FOR EACH ROW EXECUTE FUNCTION public.update_current_band_from_feedback();

-- Signup trigger: pin search_path like the others
CREATE OR REPLACE FUNCTION public.handle_new_user()
RETURNS TRIGGER
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
BEGIN
    INSERT INTO public.profiles (id, username, email)
    VALUES (
        NEW.id,
        LEFT(COALESCE(NULLIF(TRIM(NEW.raw_user_meta_data->>'username'), ''), split_part(NEW.email, '@', 1)), 40),
        NEW.email
    )
    ON CONFLICT (id) DO NOTHING;
    RETURN NEW;
END;
$$;

-- --------------------------------------------
-- 7. Leaderboard: minutes practised since a date
-- --------------------------------------------
CREATE OR REPLACE FUNCTION public.leaderboard(since TIMESTAMPTZ, lim INTEGER DEFAULT 50)
RETURNS TABLE (
    id UUID,
    username TEXT,
    avatar_url TEXT,
    current_band NUMERIC,
    current_streak INTEGER,
    sessions BIGINT,
    minutes BIGINT
)
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = public
AS $$
    WITH calls AS (
        SELECT user1_id AS u, EXTRACT(EPOCH FROM (ended_at - started_at)) AS s
        FROM public.matches
        WHERE status = 'finished' AND started_at IS NOT NULL AND ended_at >= since
        UNION ALL
        SELECT user2_id, EXTRACT(EPOCH FROM (ended_at - started_at))
        FROM public.matches
        WHERE status = 'finished' AND started_at IS NOT NULL AND ended_at >= since
    ),
    agg AS (
        SELECT u, COUNT(*) AS n, SUM(LEAST(90, ROUND(s / 60)))::BIGINT AS mins
        FROM calls WHERE s >= 60 GROUP BY u
    )
    SELECT p.id, p.username, p.avatar_url, p.current_band, p.current_streak, agg.n, agg.mins
    FROM agg JOIN public.profiles p ON p.id = agg.u
    ORDER BY agg.mins DESC, agg.n DESC, p.username
    LIMIT LEAST(GREATEST(lim, 1), 200);
$$;
REVOKE ALL ON FUNCTION public.leaderboard(TIMESTAMPTZ, INTEGER) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.leaderboard(TIMESTAMPTZ, INTEGER) TO authenticated, service_role;

-- --------------------------------------------
-- 8. Abandoned matches (the app also does this per user; a cron is optional)
-- --------------------------------------------
CREATE OR REPLACE FUNCTION public.expire_stale_matches()
RETURNS VOID
LANGUAGE sql
SECURITY DEFINER
SET search_path = public
AS $$
    -- Nobody pressed Ready in 2 minutes
    UPDATE public.matches SET status = 'cancelled', ended_at = NOW()
    WHERE status = 'pending' AND created_at < NOW() - INTERVAL '2 minutes';
    -- The call never started (one person never joined)
    UPDATE public.matches SET status = 'cancelled', ended_at = NOW()
    WHERE status = 'active' AND started_at IS NULL AND created_at < NOW() - INTERVAL '10 minutes';
    -- Both screens went quiet: end the call at the last sign of life
    UPDATE public.matches
    SET status = 'finished', ended_at = COALESCE(last_activity_at, started_at)
    WHERE status = 'active' AND started_at IS NOT NULL
      AND COALESCE(last_activity_at, started_at) < NOW() - INTERVAL '5 minutes';
    DELETE FROM public.match_queue WHERE last_seen_at < NOW() - INTERVAL '10 minutes';
$$;
REVOKE ALL ON FUNCTION public.expire_stale_matches() FROM PUBLIC, anon, authenticated;

-- To run it every 5 minutes (Database > Extensions > enable pg_cron first):
-- SELECT cron.schedule('oratio-expire-matches', '*/5 * * * *', 'SELECT public.expire_stale_matches()');

-- --------------------------------------------
-- 9. Indexes
-- --------------------------------------------
CREATE INDEX IF NOT EXISTS idx_feedback_to_user_created ON public.session_feedback(to_user_id, created_at);
CREATE INDEX IF NOT EXISTS idx_matches_finished_ended ON public.matches(ended_at) WHERE status = 'finished';
CREATE INDEX IF NOT EXISTS idx_matches_open_user1 ON public.matches(user1_id) WHERE status IN ('pending', 'active');
CREATE INDEX IF NOT EXISTS idx_matches_open_user2 ON public.matches(user2_id) WHERE status IN ('pending', 'active');

-- Make PostgREST pick up the new view and functions
NOTIFY pgrst, 'reload schema';

